ST.xhtml:
// Установка глобального ID активного ПЛК (в реальной системе это определяется через механизм Heartbeat/Redundancy)
// Для ПЛК A: если он активен, G_Active_PLC_ID := 1
PRG_Main();

IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

// 1. Автоматическое закрытие при постановке на охрану
IF VI_Armed AND NOT L_Prev_Armed THEN
    L_Auto_Lock_Req := TRUE;
END_IF;
L_Prev_Armed := VI_Armed;

// 2. Логика импульсов
// Ворота
L_Gate_Timer(IN := VI_Gate_Open_Req, PT := TO_TIME(VI_Config.gate_open_pulse_ms));
VO_Gate_Open := VI_Gate_Open_Req AND NOT L_Gate_Timer.Q;

// Калитка
L_Wicket_Timer(IN := VI_Wicket_Open_Req, PT := TO_TIME(VI_Config.wicket_open_pulse_ms));
VO_Wicket_Open := VI_Wicket_Open_Req AND NOT L_Wicket_Timer.Q;

// Замок 1
L_Lock_1_Open_T(IN := VI_Lock_1_Open_Req, PT := TO_TIME(VI_Config.lock_open_pulse_ms));
VO_Lock_1_Open := VI_Lock_1_Open_Req AND NOT L_Lock_1_Open_T.Q;

L_Lock_1_Close_T(IN := (VI_Lock_1_Close_Req OR L_Auto_Lock_Req), PT := TO_TIME(VI_Config.lock_close_pulse_ms));
VO_Lock_1_Close := (VI_Lock_1_Close_Req OR L_Auto_Lock_Req) AND NOT L_Lock_1_Close_T.Q;

// Замок 2
L_Lock_2_Open_T(IN := VI_Lock_2_Open_Req, PT := TO_TIME(VI_Config.lock_open_pulse_ms));
VO_Lock_2_Open := VI_Lock_2_Open_Req AND NOT L_Lock_2_Open_T.Q;

L_Lock_2_Close_T(IN := (VI_Lock_2_Close_Req OR L_Auto_Lock_Req), PT := TO_TIME(VI_Config.lock_close_pulse_ms));
VO_Lock_2_Close := (VI_Lock_2_Close_Req OR L_Auto_Lock_Req) AND NOT L_Lock_2_Close_T.Q;

// Сброс авто-закрытия после завершения импульса
IF L_Lock_1_Close_T.Q AND L_Lock_2_Close_T.Q THEN
    L_Auto_Lock_Req := FALSE;
END_IF;

VO_Code_Valid := FALSE;
FOR L_i := 1 TO 5 DO
    IF L_Codes[L_i] = VI_Code_To_Check THEN
        VO_Code_Valid := TRUE;
        RETURN;
    END_IF;
END_FOR;

// Упрощенная логика астро-таймера (ТЗ 15.2)
// В реальном проекте используется библиотека SysTimeRtc или расчет по формулам
L_Current_TOD := UDINT_TO_TOD(VI_System_Time_MS MOD 86400000);

// Примерные значения для средней полосы
VO_Sunrise_Time := TOD#06:00;
VO_Sunset_Time := TOD#18:00;

// ТЗ 15.2: Закат + 30 мин / Рассвет - 30 мин
VO_Is_Night := (L_Current_TOD > (VO_Sunset_Time + T#30m)) OR (L_Current_TOD < (VO_Sunrise_Time - T#30m));

CASE L_State OF
    0: // Циклическая запись
        IF NOT G_BlackBox_Frozen THEN
            G_BlackBox_Buffer[L_Write_Index] := VI_Current_Data;
            G_BlackBox_LastIndex := L_Write_Index;

            L_Write_Index := L_Write_Index + 1;
            IF L_Write_Index > 99 THEN
                L_Write_Index := 0;
            END_IF;

            IF VI_Freeze THEN
                G_BlackBox_Frozen := TRUE;
                L_State := 1;
            END_IF;
        END_IF;

    1: // Сохранение на Flash (SD-карту или внутреннюю память ПЛК210)
        L_FileHandle := SysFileOpen(L_FileName, AM_WRITE, ADR(L_FileResult));
        IF L_FileResult = 0 THEN
            SysFileWrite(L_FileHandle, ADR(G_BlackBox_Buffer[0]), SIZEOF(G_BlackBox_Buffer), ADR(L_FileResult));
            SysFileClose(L_FileHandle);
            L_State := 2;
        END_IF;

    2: // Завершено
        ;
END_CASE;

// Логика ротации по наработке
IF (VI_System_Time - L_Last_Hour_Update) >= 3600000 THEN // Раз в час
    L_Last_Hour_Update := VI_System_Time;
    IF VO_Boiler1_On THEN L_Boiler1_Hours := L_Boiler1_Hours + 1; END_IF;
    IF VO_Boiler2_On THEN L_Boiler2_Hours := L_Boiler2_Hours + 1; END_IF;

    // Смена ведущего, если разница более 100 часов
    IF (L_Boiler1_Hours > L_Boiler2_Hours + 100) THEN
        L_Lead_Boiler := 2;
    ELSIF (L_Boiler2_Hours > L_Boiler1_Hours + 100) THEN
        L_Lead_Boiler := 1;
    END_IF;
END_IF;

IF VI_IsActivePLC THEN
    IF VI_Demand_kW > 24.0 THEN
        VO_Boiler1_On := TRUE;
        VO_Boiler2_On := TRUE;
    ELSIF VI_Demand_kW > 2.0 THEN
        VO_Boiler1_On := (L_Lead_Boiler = 1);
        VO_Boiler2_On := (L_Lead_Boiler = 2);
    ELSE
        VO_Boiler1_On := FALSE;
        VO_Boiler2_On := FALSE;
    END_IF;
END_IF;

// Логика п. 2.8: Включение резервного при >80% мощности или отказе
IF VI_Boiler1_Status.Error OR VI_Boiler1_Status.Current_Power > 80.0 THEN
    VO_Boiler2_Enable := TRUE;
ELSE
    VO_Boiler2_Enable := FALSE;
END_IF;

VO_Boiler1_Enable := NOT VI_Boiler1_Status.Error;

// 1. Расчет калиброванного значения
CASE VI_Type OF
    1: VO_Calibrated_Value := VI_Raw_Value + VI_Calib_Record.offset;
    2, 3: VO_Calibrated_Value := (VI_Raw_Value * VI_Calib_Record.multiplier) + VI_Calib_Record.offset;
END_CASE;

// 2. Верификация через 1 час (ТЗ 9.5)
IF VI_Start_Verification AND NOT VO_Verification_Active THEN
    VO_Verification_Active := TRUE;
    L_Initial_Value := VO_Calibrated_Value;
    L_Verification_Timer(IN := TRUE, PT := T#1h);
END_IF;

L_Verification_Timer(IN := VO_Verification_Active);

IF L_Verification_Timer.Q THEN
    VO_Verification_Active := FALSE;
    L_Verification_Timer(IN := FALSE);

    // ТЗ 9.5: Отклонение ≤2.0% (норма) / >5.0% (ошибка)
    IF L_Initial_Value <> 0 THEN
        VO_Deviation_Percent := ABS(VO_Calibrated_Value - L_Initial_Value) / L_Initial_Value * 100.0;
    ELSE
        VO_Deviation_Percent := 0.0;
    END_IF;

    VO_Verification_Failed := (VO_Deviation_Percent > 5.0);
END_IF;

IF L_Initialized THEN RETURN; END_IF;

FOR L_i := 0 TO 255 DO
    L_Entry := TO_DWORD(L_i);
    FOR L_j := 0 TO 7 DO
        IF (L_Entry AND 1) <> 0 THEN
            L_Entry := SHR(L_Entry, 1) XOR 16#EDB88320;
        ELSE
            L_Entry := SHR(L_Entry, 1);
        END_IF;
    END_FOR;
    L_Table[L_i] := L_Entry;
END_FOR;
L_Initialized := TRUE;

InitTable();

IF VI_DataPtr = 0 OR VI_Size = 0 THEN
    Calculate := 0;
    RETURN;
END_IF;

FOR L_k := 0 TO VI_Size - 1 DO
    L_CRC := L_Table[TO_INT((L_CRC XOR VI_DataPtr[TO_INT(L_k)]) AND 16#FF)] XOR SHR(L_CRC, 8);
END_FOR;

Calculate := L_CRC XOR 16#FFFFFFFF;

// Цикл логирования
IF VI_Config.enabled AND (VI_System_Time_MS - L_last_log_time >= VI_Config.sampling_period_ms) THEN
    L_last_log_time := VI_System_Time_MS;

    // Логируем температуры (если изменились или по таймауту)
    FOR L_i := 1 TO 16 DO
        L_buffer[L_write_idx].timestamp_ms := VI_System_Time_MS;
        L_buffer[L_write_idx].level := E_Debug_Log_Level.LOG_LEVEL_VERBOSE;
        L_buffer[L_write_idx].source_id := TO_BYTE(L_i);
        L_buffer[L_write_idx].value_real := VI_Floor_Temps[L_i];
        L_buffer[L_write_idx].text := 'Floor Temp Update';

        L_write_idx := (L_write_idx MOD 1000) + 1;
    END_FOR;

    // Логируем ошибки
    IF VI_Error_Code <> 0 THEN
        L_buffer[L_write_idx].timestamp_ms := VI_System_Time_MS;
        L_buffer[L_write_idx].level := E_Debug_Log_Level.LOG_LEVEL_MINIMAL;
        L_buffer[L_write_idx].event_code := TO_WORD(VI_Error_Code);
        L_buffer[L_write_idx].text := 'System Error Detected';
        L_write_idx := (L_write_idx MOD 1000) + 1;
    END_IF;
END_IF;

// 1. Счётчик пусков и замер пускового тока
IF VI_Is_Running AND NOT L_Prev_Running THEN
    VIO_Health_Data.Starts_Count := VIO_Health_Data.Starts_Count + 1;
    VIO_Health_Data.Last_Start_Current := VI_Current_Value;

    // Обновление среднего пускового тока
    L_Sample_Count := L_Sample_Count + 1;
    L_Current_Sum := L_Current_Sum + VI_Current_Value;
    VIO_Health_Data.Avg_Start_Current := L_Current_Sum / UDINT_TO_REAL(L_Sample_Count);
END_IF;

// 2. Анализ отклонения (п. 12.1 ТЗ)
IF VI_Is_Running THEN
    // Если ток выше номинала на 50% - снижаем здоровье
    IF VI_Current_Value > (VI_Nominal_Value * 1.5) THEN
        IF VIO_Health_Data.Health_Score > 0 THEN
            VIO_Health_Data.Health_Score := VIO_Health_Data.Health_Score - 1;
        END_IF;
    END_IF;
END_IF;

// 3. Генерация предупреждения
IF VIO_Health_Data.Health_Score < 20 THEN
    VIO_Health_Data.Maintenance_Required := TRUE;
    VIO_Health_Data.Warning_Message := 'Критический износ: проверьте механику';
ELSIF VIO_Health_Data.Health_Score < 60 THEN
    VIO_Health_Data.Warning_Message := 'Предупреждение: повышенное трение';
END_IF;

L_Prev_Running := VI_Is_Running;

// 1. Обработка неисправности (ТЗ 7.0)
IF VI_Maintenance.Is_Faulty OR VI_Maintenance.Is_In_Maintenance THEN
    VO_Status.Temp := SEL(VI_Maintenance.Use_Last_Good_Value, VI_Maintenance.Fallback_Value, L_Last_Good_Temp);
ELSE
    VO_Status.Temp := VI_Temp;
    L_Last_Good_Temp := VI_Temp;
END_IF;

VO_Status.Pressure := VI_Pressure;

// 2. Логика нагрева
IF VI_IsActivePLC THEN
    IF VO_Status.Temp < (VI_Config.Target_Temp - VI_Config.Hysteresis) THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > (VI_Config.Target_Temp + VI_Config.Hysteresis) THEN
        VO_Heating_Pump := FALSE;
    END_IF;

    // 3. Циркуляция ГВС по расписанию
    L_Current_TOD := UDINT_TO_TOD(VI_System_Time_MS MOD 86400000);
    VO_Circ_Pump := VI_Config.Circulation_Schedule_Enabled AND 
                    (L_Current_TOD >= VI_Config.Circulation_Start AND L_Current_TOD <= VI_Config.Circulation_End);
ELSE
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
END_IF;

VO_Status.Heating_Pump_On := VO_Heating_Pump;
VO_Status.Circ_Pump_On := VO_Circ_Pump;
VO_Status.Error := (VI_Pressure < 1.0 OR VI_Pressure > 4.0);

IF VI_Humidity > VI_Config.Threshold_Hum THEN
    VO_Fan_Speed := 100;
ELSIF VI_CO2 > 800.0 THEN
    VO_Fan_Speed := 70;
ELSE
    VO_Fan_Speed := 40;
END_IF;

VO_Flood_Alarm := FALSE;
VO_Close_Valve_35 := FALSE;
VO_Close_Valve_36 := FALSE;

FOR L_i := 1 TO 12 DO
    IF VI_Sensors[L_i] THEN
        VO_Flood_Alarm := TRUE;
        IF VI_IsActivePLC THEN
            // Логика п. 4.2: Зона 2 (4-5) и Зона 3 (6-7) делят клапан 36
            IF L_i >= 4 AND L_i <= 7 THEN
                VO_Close_Valve_36 := TRUE;
            ELSIF L_i >= 1 AND L_i <= 3 THEN
                VO_Close_Valve_35 := TRUE;
            END_IF;
        END_IF;
    END_IF;
END_FOR;

// 1. Определение активного тарифа
IF VI_Tariff.Enabled THEN
    IF VI_Tariff.Night_Start_Hour > VI_Tariff.Night_End_Hour THEN
        // Переход через полночь (например, 23:00 - 07:00)
        L_Is_Night := (VI_Current_Hour >= VI_Tariff.Night_Start_Hour) OR (VI_Current_Hour < VI_Tariff.Night_End_Hour);
    ELSE
        // В пределах одного дня
        L_Is_Night := (VI_Current_Hour >= VI_Tariff.Night_Start_Hour) AND (VI_Current_Hour < VI_Tariff.Night_End_Hour);
    END_IF;
ELSE
    L_Is_Night := FALSE;
END_IF;

// 2. Расчет эффективной уставки
VO_Effective_Setpoint := VI_Config.design_temp;
IF L_Is_Night THEN
    VO_Effective_Setpoint := VO_Effective_Setpoint + VI_Tariff.Boost_Delta;
END_IF;

// 3. Простая логика управления (гистерезис)
IF VI_IsActivePLC THEN
    IF VI_Current_Temp < (VO_Effective_Setpoint - 0.5) THEN
        VO_Pump_Run := TRUE;
        VO_Valve_Pos := 10.0;
    ELSIF VI_Current_Temp > (VO_Effective_Setpoint + 0.5) THEN
        VO_Pump_Run := FALSE;
        VO_Valve_Pos := 0.0;
    END_IF;
END_IF;

VO_Freeze_Alert := FALSE;
VO_Pump_Force_On := FALSE;

FOR L_i := 1 TO 16 DO
    IF VI_Floor_Temps[L_i] < VI_Threshold THEN
        VO_Freeze_Alert := TRUE;
        VO_Pump_Force_On := TRUE;
        RETURN;
    END_IF;
END_FOR;

IF VI_Outdoor_Temp < -5.0 THEN
    VO_Pump_Force_On := TRUE;
END_IF;

VO_Overheat_Detected := FALSE;
FOR L_i := 1 TO 16 DO
    IF VI_Temps[L_i] > VI_Threshold THEN
        VO_Overheat_Detected := TRUE;
        VO_Locked_Circuits[L_i] := TRUE;
    END_IF;
END_FOR;

// 1. Обработка метана (ТЗ 5.1, 6.4)
L_Methane_Max := 0.0;
FOR L_i := 1 TO 2 DO IF VI_Methane_LEL[L_i] > L_Methane_Max THEN L_Methane_Max := VI_Methane_LEL[L_i]; END_IF; END_FOR;

VO_Vent_PV3_Boost := (L_Methane_Max >= 10.0); // ТЗ 5.1: ПВ-3 при 10% LEL

IF L_Methane_Max >= 40.0 THEN
    VO_Gas_Alarm := TRUE; VO_Gas_Valve_Close := TRUE; VO_Boiler_Stop := TRUE; VO_Supply_100_Req := TRUE;
    VO_Status_Msg := 'КРИТИЧЕСКАЯ УТЕЧКА ГАЗА (40% LEL)';
ELSIF L_Methane_Max >= 20.0 THEN
    VO_Gas_Alarm := TRUE; VO_Gas_Valve_Close := TRUE; VO_Boiler_Stop := TRUE; VO_Supply_100_Req := TRUE;
    VO_Status_Msg := 'УТЕЧКА ГАЗА (20% LEL)';
ELSIF L_Methane_Max >= 10.0 THEN 
    VO_Status_Msg := 'ПРЕДУПРЕЖДЕНИЕ: ГАЗ (10% LEL)';
END_IF;

// 2. Обработка CO (ТЗ 5.2, 5.4)
L_CO_Max := 0.0;
FOR L_i := 1 TO 8 DO IF VI_CO_PPM[L_i] > L_CO_Max THEN L_CO_Max := VI_CO_PPM[L_i]; END_IF; END_FOR;

L_CO_Timer_30ppm(IN := (L_CO_Max >= 30.0), PT := T#8h);
L_CO_Timer_70ppm(IN := (L_CO_Max >= 70.0), PT := T#1h);
L_CO_Timer_400ppm(IN := (L_CO_Max >= 400.0), PT := T#15m);

IF L_CO_Timer_400ppm.Q THEN VO_Gas_Alarm := TRUE; VO_Status_Msg := 'КРИТИЧЕСКАЯ КОНЦЕНТРАЦИЯ CO (400 ppm / 15 мин)';
ELSIF L_CO_Timer_70ppm.Q THEN VO_Gas_Alarm := TRUE; VO_Status_Msg := 'ВЫСОКАЯ КОНЦЕНТРАЦИЯ CO (70 ppm / 1 час)';
ELSIF L_CO_Timer_30ppm.Q THEN VO_Gas_Alarm := TRUE; VO_Status_Msg := 'ПОВЫШЕННАЯ КОНЦЕНТРАЦИЯ CO (30 ppm / 8 час)';
END_IF;

IF VO_Gas_Alarm AND L_CO_Max >= 30.0 THEN VO_Supply_80_Req := TRUE; END_IF; // ТЗ 5.4

// 3. Обработка дыма (ТЗ 5.3, 6.4)
L_Smoke_Count := 0;
FOR L_i := 1 TO 6 DO
    L_Smoke_Timer[L_i](IN := VI_Smoke_Sensors[L_i], PT := T#30s);
    IF VI_Smoke_Sensors[L_i] THEN L_Smoke_Count := L_Smoke_Count + 1; END_IF;
    // ТЗ 5.3: Верификация вторым датчиком ИЛИ сигнал > 30 сек
    IF L_Smoke_Timer[L_i].Q OR (L_Smoke_Count >= 2) THEN L_Smoke_Active := TRUE; END_IF;
END_FOR;

IF L_Smoke_Active THEN 
    VO_Fire_Alarm := TRUE; VO_Boiler_Stop := TRUE; VO_Exhaust_100_Req := TRUE;
    VO_Status_Msg := 'ПОЖАРНАЯ ТРЕВОГА: ДЫМ'; 
END_IF;

// 4. Сирена и квитирование (ТЗ 5.5)
IF VO_Gas_Alarm OR VO_Fire_Alarm THEN
    IF VI_Mute_Request AND NOT L_Muted AND L_Mute_Count < 3 THEN
        L_Muted := TRUE; L_Mute_Count := L_Mute_Count + 1;
        L_Mute_Timer(IN := TRUE, PT := T#5m);
    END_IF;

    L_Mute_Timer(IN := L_Muted);
    IF L_Mute_Timer.Q THEN L_Muted := FALSE; L_Mute_Timer(IN := FALSE); END_IF;
    VO_Siren_Active := NOT L_Muted;
ELSE
    L_Muted := FALSE; L_Mute_Count := 0; VO_Siren_Active := FALSE;
END_IF;

// При аварии газа - немедленное закрытие
IF VI_Gas_Alarm AND VI_IsActivePLC THEN
    VO_Valve_Closed := TRUE;
    VO_Status_Msg := 'ГАЗОВЫЙ КЛАПАН ЗАКРЫТ ПО АВАРИИ';
END_IF;

IF VI_IsActivePLC OR VI_Force THEN
    VO_Valve_Closed := FALSE;
    OpenValve := TRUE;
END_IF;

// Обновление данных Modbus (раз в 1 сек)
IF (VI_System_Time_MS - L_last_update_time) >= 1000 THEN
    L_last_update_time := VI_System_Time_MS;

    // 0: Статус ПЛК и Аварии
    L_tmp_word := 0;
    IF VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE THEN L_tmp_word := L_tmp_word OR 1; END_IF;
    IF VI_Security_Armed THEN L_tmp_word := L_tmp_word OR 2; END_IF;
    IF VI_Flood_Alarm_Active THEN L_tmp_word := L_tmp_word OR 4; END_IF;
    IF VI_Gas_Alarm_Active THEN L_tmp_word := L_tmp_word OR 8; END_IF;
    IF VI_Fire_Alarm_Active THEN L_tmp_word := L_tmp_word OR 16; END_IF;
    VO_Modbus_Registers[0] := L_tmp_word;

    // 1-16: Температуры пола (x10)
    FOR L_i := 1 TO 16 DO
        VO_Modbus_Registers[L_i] := TO_WORD(TO_INT(VI_FloorHeating_Temps[L_i] * 10.0));
    END_FOR;

    // 17-32: Температуры помещений (x10)
    FOR L_i := 1 TO 16 DO
        VO_Modbus_Registers[16 + L_i] := TO_WORD(TO_INT(VI_Room_Temps[L_i] * 10.0));
    END_FOR;

    // 33: Состояние клапанов зон (битовая маска 1-16)
    L_tmp_word := 0;
    FOR L_i := 1 TO 16 DO
        IF VI_Zone_Valve_States[L_i] THEN
            L_tmp_word := L_tmp_word OR SHL(TO_WORD(1), L_i - 1);
        END_IF;
    END_FOR;
    VO_Modbus_Registers[33] := L_tmp_word;

    // 34-38: Давление в коллекторах (x100)
    FOR L_i := 1 TO 5 DO
        VO_Modbus_Registers[33 + L_i] := TO_WORD(TO_INT(VI_Manifold_Pressures[L_i] * 100.0));
    END_FOR;

    // 40-55: Базовое освещение
    FOR L_i := 1 TO 16 DO
        VO_Modbus_Registers[39 + L_i] := TO_WORD(VI_Lighting_Base_Levels[L_i]);
    END_FOR;

    // 60-79: Положение штор (20 шт)
    FOR L_i := 1 TO 20 DO
        VO_Modbus_Registers[59 + L_i] := TO_WORD(VI_Blinds_Positions[L_i]);
    END_FOR;

    // 80-82: Розетки (битовая маска, 36 розеток -> 3 WORD)
    FOR L_i := 0 TO 2 DO
        L_tmp_word := 0;
        FOR L_j := 1 TO 16 DO
            L_idx := (L_i * 16) + L_j;
            IF L_idx <= 36 THEN
                IF VI_Socket_States[L_idx] THEN
                    L_tmp_word := L_tmp_word OR SHL(TO_WORD(1), L_j - 1);
                END_IF;
            END_IF;
        END_FOR;
        VO_Modbus_Registers[79 + L_i] := L_tmp_word;
    END_FOR;

    VO_Data_Ready := TRUE;
END_IF;

// Обработка входящих команд
IF VI_Command_Received AND (VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE) THEN
    CASE VI_Incoming_Command.command_type OF
        1: // Управление сценариями
            GVL_Vars.G_Current_Scenario := VI_Incoming_Command.target_scenario;
            VO_HMI_Status_Message := 'Gateway: Сценарий изменен';
        2: // Управление освещением
            IF (VI_Incoming_Command.target_zone >= 1) AND (VI_Incoming_Command.target_zone <= 16) THEN
                VO_Lighting_Override[VI_Incoming_Command.target_zone] := TO_BYTE(VI_Incoming_Command.target_value);
                VO_HMI_Status_Message := 'Gateway: Команда освещения принята';
            END_IF;
        3: // Розетки
            IF (VI_Incoming_Command.target_zone >= 1) AND (VI_Incoming_Command.target_zone <= 36) THEN
                VO_Socket_Override[VI_Incoming_Command.target_zone] := VI_Incoming_Command.target_on_off;
            END_IF;
        4: // Охрана
            // Логика постановки/снятия через PIN в FB_Security_System_Manager
            // Здесь можно только передать запрос
            VO_HMI_Status_Message := 'Gateway: Запрос охраны принят';
    END_CASE;
END_IF;

// 1. Расчет целевой температуры подачи (ТЗ 2.3)
L_Target_Supply_Temp := 35.0;
IF VI_Config.Weather_Comp_Enabled AND VI_Outdoor_Temp < 15.0 THEN
    // Исправлено: убран множитель 10.0 согласно ТЗ 2.3
    L_Target_Supply_Temp := L_Target_Supply_Temp + (15.0 - VI_Outdoor_Temp) * VI_Config.Weather_Coef;
END_IF;
L_Target_Supply_Temp := LIMIT(20.0, L_Target_Supply_Temp, 45.0);

// 2. Управление зонами (ТЗ 1.1, 2.5)
FOR L_i := 1 TO 16 DO
    L_Overheat_Timer[L_i](IN := VI_Floor_Temps[L_i] > VI_Config.Overheat_Threshold, PT := T#60s);

    IF VI_Room_Temps[L_i] < (VI_Config.Target_Room_Temp - VI_Config.Hysteresis) THEN
        VO_Zone_Valves[L_i] := TRUE;
    ELSIF VI_Room_Temps[L_i] > (VI_Config.Target_Room_Temp + VI_Config.Hysteresis) THEN
        VO_Zone_Valves[L_i] := FALSE;
    END_IF;

    // Защита от перегрева с задержкой 60с (ТЗ 2.5)
    IF L_Overheat_Timer[L_i].Q THEN
        VO_Zone_Valves[L_i] := FALSE;
    END_IF;
END_FOR;

// 3. Активность коллекторов
L_Any_Zone_Active[1] := VO_Zone_Valves[1] OR VO_Zone_Valves[2];
L_Any_Zone_Active[2] := VO_Zone_Valves[3] OR VO_Zone_Valves[4] OR VO_Zone_Valves[5] OR VO_Zone_Valves[6];
L_Any_Zone_Active[3] := VO_Zone_Valves[7] OR VO_Zone_Valves[8] OR VO_Zone_Valves[9];
L_Any_Zone_Active[4] := VO_Zone_Valves[10] OR VO_Zone_Valves[11] OR VO_Zone_Valves[12];
L_Any_Zone_Active[5] := VO_Zone_Valves[13] OR VO_Zone_Valves[14] OR VO_Zone_Valves[15] OR VO_Zone_Valves[16];

// 4. Управление коллекторами (ТЗ 2.6, 12.2)
FOR L_i := 1 TO 5 DO
    L_PID_Valves[L_i](
        VI_SetPoint := L_Target_Supply_Temp,
        VI_ProcessValue := VI_Manifold_Temps_Supply[L_i],
        VI_Kp := 2.0, VI_Tn := 120.0, VI_Tv := 0.0,
        VI_Y_Min := 0.0, VI_Y_Max := 100.0, VI_Cycle_Time_S := 1.0,
        VO_Output => VO_Manifold_Valves[L_i]
    );

    // ТЗ 2.6: Пауза после 72 часов работы
    L_Pump_Run_Timer[L_i](IN := VO_Manifold_Pumps[L_i] AND NOT L_Pump_In_Pause[L_i], PT := T#72h);
    IF L_Pump_Run_Timer[L_i].Q THEN L_Pump_In_Pause[L_i] := TRUE; END_IF;

    L_Pump_Pause_Timer[L_i](IN := L_Pump_In_Pause[L_i], PT := T#1h);
    IF L_Pump_Pause_Timer[L_i].Q THEN L_Pump_In_Pause[L_i] := FALSE; END_IF;

    VO_Manifold_Pumps[L_i] := VI_IsActivePLC AND L_Any_Zone_Active[L_i] AND NOT L_Pump_In_Pause[L_i];

    // Защита от замерзания (ТЗ 2.4)
    IF VI_Outdoor_Temp < -5.0 OR VI_Manifold_Temps_Supply[L_i] < VI_Config.Freeze_Threshold THEN
        VO_Manifold_Pumps[L_i] := TRUE;
        VO_Manifold_Valves[L_i] := 100.0;
    END_IF;

    // Диагностика (ТЗ 2.6)
    VO_Status[L_i].Pump_On := VO_Manifold_Pumps[L_i];
    VO_Status[L_i].Pump_Current := VI_Manifold_Currents[L_i];
    VO_Status[L_i].Pressure := VI_Manifold_Pressures[L_i];
    VO_Status[L_i].Temp_Supply := VI_Manifold_Temps_Supply[L_i];
    VO_Status[L_i].Temp_Return := VI_Manifold_Temps_Return[L_i];
    VO_Status[L_i].Valve_Pos := VO_Manifold_Valves[L_i];

    // Контроль давления (1.5-2.5 бар) и Delta T (5-10C)
    IF VO_Manifold_Pumps[L_i] THEN
        IF VI_Manifold_Pressures[L_i] < 1.5 OR VI_Manifold_Pressures[L_i] > 2.5 THEN
            VO_Status[L_i].Error := TRUE; VO_Status[L_i].Error_ID := 16#E004; // Pressure Out of Range
        END_IF;
        // Исправлено: порог Delta T снижен до 10.0 согласно ТЗ 2.6
        IF (VI_Manifold_Temps_Supply[L_i] - VI_Manifold_Temps_Return[L_i]) > 10.0 THEN
            VO_Status[L_i].Error := TRUE; VO_Status[L_i].Error_ID := 16#E005; // High Delta T
        END_IF;
    END_IF;

    // Тестирование арматуры (ТЗ 12.2)
    IF (VI_System_Time_MS MOD 604800000) < 10000 THEN VO_Manifold_Valves[L_i] := 20.0; END_IF;
END_FOR;

// 5. Каскад котлов (ТЗ 2.8, 12.3)
L_Demand_Power := 0.0;
FOR L_i := 1 TO 5 DO IF VO_Manifold_Pumps[L_i] THEN L_Demand_Power := L_Demand_Power + VO_Manifold_Valves[L_i]; END_IF; END_FOR;
L_Demand_Power := L_Demand_Power / 5.0;

IF (VI_System_Time_MS - L_Last_Boiler_Rotation) > 604800000 THEN
    L_Last_Boiler_Rotation := VI_System_Time_MS;
    L_Lead_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);
END_IF;

IF VI_IsActivePLC AND L_Demand_Power > 5.0 THEN
    VO_Boiler_Enable[L_Lead_Boiler] := TRUE;
    VO_Boiler_Setpoint[L_Lead_Boiler] := L_Target_Supply_Temp + 5.0; // OpenTherm Setpoint
    VO_Boiler_Enable[3 - L_Lead_Boiler] := (L_Demand_Power > 80.0);
    VO_Boiler_Setpoint[3 - L_Lead_Boiler] := SEL(L_Demand_Power > 80.0, 0.0, L_Target_Supply_Temp + 5.0);
ELSE
    VO_Boiler_Enable[1] := FALSE; VO_Boiler_Enable[2] := FALSE;
END_IF;

// Учет наработки (ТЗ 2.8, 12.3)
FOR L_i := 1 TO 2 DO
    IF VI_Boiler_Flame_Status[L_i] THEN
        VO_Boiler_Status[L_i].Work_Seconds := VO_Boiler_Status[L_i].Work_Seconds + 1; // Assuming 1s cycle for this FB or call
        VO_Boiler_Status[L_i].Work_Hours := TO_REAL(VO_Boiler_Status[L_i].Work_Seconds) / 3600.0;
        VO_Boiler_Status[L_i].Resource_Percent := (1.0 - (TO_REAL(VO_Boiler_Status[L_i].Work_Seconds) / L_Lifespan_S)) * 100.0;
    END_IF;
    VO_Boiler_Status[L_i].Running := VI_Boiler_Flame_Status[L_i];
END_FOR;

IF VI_Write_Event THEN
    L_History_Buffer[L_Write_Idx] := VI_Event;
    L_History_Buffer[L_Write_Idx].timestamp_ms := VI_System_Time_MS;

    L_Write_Idx := (L_Write_Idx MOD 100) + 1;
    VO_Total_Events := VO_Total_Events + 1;
END_IF;

// Упрощенная модель износа
IF VI_Nominal_Life > 0 THEN
    VO_Remaining_Percent := TO_BYTE(100 - (VI_Runtime_Hours * 100 / VI_Nominal_Life));
ELSE
    VO_Remaining_Percent := 0;
END_IF;

VO_Maintenance_Req := (VO_Remaining_Percent < 10);

// 1. Определение базовых уровней по сценарию (ТЗ 7.1)
CASE VI_Current_Scenario OF
    E_SCENARIO_TYPE.SCENARIO_MORNING:
        L_Base_Light := 70;
        L_Base_Blinds := 80; // 80% открыты

    E_SCENARIO_TYPE.SCENARIO_EVENING:
        L_Base_Light := 40;
        L_Base_Blinds := 10; // 90% закрыты (10% открыты)

    E_SCENARIO_TYPE.SCENARIO_AWAY:
        L_Base_Light := 0;
        L_Base_Blinds := 0; // 100% закрыты

    ELSE
        L_Base_Light := 100;
        L_Base_Blinds := 100;
END_CASE;

// 2. Управление освещением
FOR L_i := 1 TO 16 DO
    // Приоритет 1: Физические выключатели (ТЗ 1.0)
    IF VI_Physical_Switches[L_i] AND NOT L_Prev_Switches[L_i] THEN
        L_Light_States[L_i] := NOT L_Light_States[L_i];
    END_IF;
    L_Prev_Switches[L_i] := VI_Physical_Switches[L_i];

    // Приоритет 2: Датчики движения (ТЗ 2.0)
    L_Motion_Timers[L_i](IN := VI_Motion_Sensors[L_i], PT := T#5m);
    IF VI_Motion_Sensors[L_i] THEN
        L_Light_States[L_i] := TRUE;
    ELSIF L_Motion_Timers[L_i].Q THEN
        L_Light_States[L_i] := FALSE;
    END_IF;

    // Приоритет 3: Симуляция (только в режиме Away)
    IF VI_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY AND VI_Simulation_Active THEN
        L_Light_States[L_i] := VI_Simulation_Lights[L_i];
    END_IF;

    // Приоритет 4: Ремонт/Неисправность (ТЗ 6.0, 7.0)
    IF VI_Maintenance[L_i].Is_Faulty OR VI_Maintenance[L_i].Is_In_Maintenance THEN
        VO_Lighting_Levels[L_i] := REAL_TO_BYTE(VI_Maintenance[L_i].Fallback_Value);
    ELSE
        VO_Lighting_Levels[L_i] := SEL(L_Light_States[L_i], 0, L_Base_Light);
    END_IF;

    // 5. Мокрые зоны (допустим зоны 13-16 - санузлы)
    IF L_i >= 13 THEN
        VO_Wet_Zone_Light_Active[L_i - 12] := (VO_Lighting_Levels[L_i] > 10);
    END_IF;
END_FOR;

// 3. Управление шторами
FOR L_i := 1 TO 20 DO
    // Приоритет 1: Ручное управление
    IF VI_Manual_Blinds_Override[L_i] > 0 THEN
        VO_Blinds_Positions[L_i] := VI_Manual_Blinds_Override[L_i];
    // Приоритет 2: Сценарий
    ELSE
        VO_Blinds_Positions[L_i] := L_Base_Blinds;
    END_IF;
END_FOR;

IF VI_Activate AND NOT VO_Active THEN
    VO_Active := TRUE;
    L_Start_Time := VI_System_Time;
END_IF;

IF VO_Active THEN
    L_elapsed := (VI_System_Time - L_Start_Time) / 60000;
    IF L_elapsed >= VI_Duration THEN
        VO_Active := FALSE;
    ELSE
        VO_Time_Left := VI_Duration - L_elapsed;
    END_IF;
END_IF;

// ПИД-регулятор (упрощенно для примера)
VO_Valve_Pos := (VI_Setpoint - VI_Actual) * 10.0;
IF VO_Valve_Pos > 100.0 THEN VO_Valve_Pos := 100.0;
ELSIF VO_Valve_Pos < 0.0 THEN VO_Valve_Pos := 0.0;
END_IF;

IF VI_Enable_Request THEN
    VO_Speed_Percent := 100;
    VO_Running := TRUE;
    L_Stopping := FALSE;
ELSE
    IF VO_Running AND NOT L_Stopping THEN
        L_Stopping := TRUE;
        L_Stop_Start_Time := VI_System_Time;
    END_IF;

    IF L_Stopping THEN
        L_elapsed := VI_System_Time - L_Stop_Start_Time;
        IF L_elapsed < VI_Stop_Ramp_MS THEN
            // Исправлено: защита от отрицательного значения
            VO_Speed_Percent := REAL_TO_BYTE(100.0 * (1.0 - TO_REAL(L_elapsed) / TO_REAL(VI_Stop_Ramp_MS)));
        ELSE
            VO_Speed_Percent := 0;
            VO_Running := FALSE;
            L_Stopping := FALSE;
        END_IF;
    END_IF;
END_IF;

// Логика ручного управления клапаном с таймером автозакрытия
IF VI_Open_Req AND NOT L_Active THEN
    L_Active := TRUE;
    L_Start_Time := VI_System_Time;
    VO_Open_Cmd := TRUE;
END_IF;

IF L_Active THEN
    // Расчет оставшегося времени в минутах
    L_elapsed := (VI_System_Time - L_Start_Time) / 60000;
    IF L_elapsed >= VI_Duration THEN
        L_Active := FALSE;
        VO_Open_Cmd := FALSE;
    ELSE
        VO_Time_Left := VI_Duration - L_elapsed;
    END_IF;
ELSE
    VO_Time_Left := 0;
END_IF;

// Логика выполнения
L_current_time := VI_System_Time_MS;

// Детекция фронта команды
L_cmd_rising := (VI_Command <> 0) AND (L_prev_Command = 0);
L_prev_Command := VI_Command;

CASE L_state OF
    0: // ОЖИДАНИЕ (IDLE)
        IF L_cmd_rising THEN
            VO_Done := FALSE;
            VO_Error := 0;

            // Валидация индекса
            IF (VI_RecordIndex < 1) OR (TO_UDINT(VI_RecordIndex) > C_MAX_RECORDS) THEN
                VO_Error := 16#1501;
                VO_HMI_Status_Message := 'NVRAM: Неверный индекс записи';
                VO_Done := TRUE;
                RETURN;
            END_IF;

            // Валидация указателя
            IF VI_DataPtr = 0 THEN
                VO_Error := 16#150A;
                VO_HMI_Status_Message := 'NVRAM: Нулевой указатель данных';
                VO_Done := TRUE;
                RETURN;
            END_IF;

            IF VI_Command = 1 THEN // ЗАПИСЬ (WRITE)
                IF NOT VI_IsActivePLC THEN
                    VO_Error := 16#1509;
                    VO_HMI_Status_Message := 'NVRAM: Запись запрещена (STANDBY)';
                    VO_Done := TRUE;
                ELSIF VI_DataSize > C_RECORD_SIZE THEN
                    VO_Error := 16#150B;
                    VO_HMI_Status_Message := 'NVRAM: Размер данных больше 128 байт';
                    VO_Done := TRUE;
                ELSE
                    L_state := 1; // Переход к записи
                    L_step := 0;
                END_IF;
            ELSIF VI_Command = 2 THEN // ЧТЕНИЕ (READ)
                L_state := 2; // Переход к чтению
                L_step := 0;
            END_IF;
        END_IF;

    1: // ЗАПИСЬ_ЗАПИСИ (WRITE_RECORD)
        CASE L_step OF
            0: // Подготовка буфера и расчет CRC
                FOR L_i := 0 TO C_RECORD_SIZE - 1 DO
                    IF L_i < VI_DataSize THEN
                        L_temp_buffer[TO_INT(L_i + 1)] := VI_DataPtr[TO_INT(L_i)];
                    ELSE
                        L_temp_buffer[TO_INT(L_i + 1)] := 16#00;
                    END_IF;
                END_FOR;
                L_data_crc := L_crc32.Calculate(ADR(L_temp_buffer[1]), C_RECORD_SIZE);
                L_step := 1;

            1: // Открытие файла для записи
                L_FileHandle := SysFileOpen(L_FileName, AM_WRITE, ADR(L_FileResult));
                IF L_FileResult = 0 THEN
                    L_step := 2;
                ELSE
                    VO_Error := 16#150C;
                    L_state := 0;
                END_IF;

            2: // Позиционирование и запись
                L_Offset := TO_DINT(VI_RecordIndex - 1) * TO_DINT(C_RECORD_TOTAL_SIZE);
                L_FileResult := SysFileSetPos(L_FileHandle, TO_UDINT(L_Offset));
                L_BytesProcessed := TO_UDINT(SysFileWrite(L_FileHandle, ADR(L_temp_buffer[1]), TO_UDINT(C_RECORD_TOTAL_SIZE), ADR(L_FileResult)));
                L_FileResult := SysFileClose(L_FileHandle);
                VO_Done := TRUE;
                L_state := 0;
        END_CASE;

    2: // ЧТЕНИЕ_ЗАПИСИ (READ_RECORD)
        CASE L_step OF
            0: // Открытие файла для чтения
                L_FileHandle := SysFileOpen(L_FileName, AM_READ, ADR(L_FileResult));
                IF L_FileResult = 0 THEN
                    L_step := 1;
                ELSE
                    VO_Error := 16#150D;
                    L_state := 0;
                END_IF;

            1: // Чтение данных
                L_Offset := TO_DINT(VI_RecordIndex - 1) * TO_DINT(C_RECORD_TOTAL_SIZE);
                L_FileResult := SysFileSetPos(L_FileHandle, TO_UDINT(L_Offset));
                L_BytesProcessed := TO_UDINT(SysFileRead(L_FileHandle, ADR(L_temp_buffer[1]), TO_UDINT(C_RECORD_TOTAL_SIZE), ADR(L_FileResult)));
                L_FileResult := SysFileClose(L_FileHandle);

                // Копирование в выходной указатель
                FOR L_i := 0 TO C_RECORD_SIZE - 1 DO
                    IF L_i < VI_DataSize THEN
                        VI_DataPtr[TO_INT(L_i)] := L_temp_buffer[TO_INT(L_i + 1)];
                    END_IF;
                END_FOR;
                VO_ReadDataPtr := VI_DataPtr;
                VO_Done := TRUE;
                L_state := 0;
        END_CASE;
END_CASE;

// Расчет ошибки
VO_Error := VI_SetPoint - VI_ProcessValue;

// Проверка мертвой зоны
IF ABS(VO_Error) < VI_Deadband THEN
    VO_Error := 0.0;
END_IF;

IF VI_Reset THEN
    L_Integral_Sum := 0.0;
    L_Prev_Error := 0.0;
    VO_Output := 0.0;
    RETURN;
END_IF;

IF VI_Manual_Mode THEN
    VO_Output := VI_Manual_Value;
    L_Integral_Sum := VO_Output; // Безударный переход
    RETURN;
END_IF;

// Пропорциональная составляющая
L_Output_Raw := VI_Kp * VO_Error;

// Интегральная составляющая (Метод трапеций)
IF VI_Tn > 0.0 THEN
    // Anti-windup: не накапливаем интеграл, если выход уже на пределе и ошибка того же знака
    IF NOT VO_Limiting OR (VO_Error > 0.0 AND L_Output_Raw < VI_Y_Max) OR (VO_Error < 0.0 AND L_Output_Raw > VI_Y_Min) THEN
        L_Integral_Sum := L_Integral_Sum + (VI_Kp / VI_Tn) * VO_Error * VI_Cycle_Time_S;
    END_IF;
    L_Output_Raw := L_Output_Raw + L_Integral_Sum;
END_IF;

// Дифференциальная составляющая
IF VI_Tv > 0.0 THEN
    L_Derivative := (VO_Error - L_Prev_Error) / VI_Cycle_Time_S;
    L_Output_Raw := L_Output_Raw + VI_Kp * VI_Tv * L_Derivative;
END_IF;

L_Prev_Error := VO_Error;

// Ограничение выхода
IF L_Output_Raw > VI_Y_Max THEN
    VO_Output := VI_Y_Max;
    VO_Limiting := TRUE;
ELSIF L_Output_Raw < VI_Y_Min THEN
    VO_Output := VI_Y_Min;
    VO_Limiting := TRUE;
ELSE
    VO_Output := L_Output_Raw;
    VO_Limiting := FALSE;
END_IF;

// 1. Мониторинг пульса и RTT (ТЗ 8.4)
IF VI_Remote_Pulse <> L_Last_Pulse THEN
    VO_RTT_MS := VI_System_Time - L_Last_Pulse_Time;
    IF VO_RTT_MS > VO_Max_RTT THEN VO_Max_RTT := VO_RTT_MS; END_IF;
    L_Last_Pulse := VI_Remote_Pulse;
    L_Last_Pulse_Time := VI_System_Time;
END_IF;

L_Loss_Timer(IN := (VI_System_Time - L_Last_Pulse_Time) > L_Timeout, PT := T#1s);
IF L_Loss_Timer.Q THEN 
    VO_Loss_Count := VO_Loss_Count + 1; 
    L_Loss_Timer(IN := FALSE); 
END_IF;

// 2. Логика активности и защита от раскола мозга (ТЗ 8.3)
// Уровень 1: Тайм-аут пульса
IF (VI_System_Time - L_Last_Pulse_Time) < L_Timeout THEN
    // Уровень 2: Если партнер заявляет, что он активен, и у него приоритет (ID=1)
    IF VI_Remote_Is_Active AND VI_Local_ID = 2 THEN
        VO_Is_Active := FALSE;
    ELSE
        // Приоритет у ПЛК A (ID=1)
        VO_Is_Active := (VI_Local_ID = 1);
    END_IF;
ELSE
    // Уровень 3: Если связи нет, проверяем доступность шлюза
    VO_Is_Active := VI_Gateway_Ping_OK OR (VI_Local_ID = 1);
END_IF;

// Запуск за 3 часа (10800000 мс)
IF (VI_Departure_Time - VI_System_Time) < 10800000 THEN
    VO_Heating_Active := TRUE;
    FOR L_i := 1 TO 16 DO
        IF VI_Selected[L_i] THEN VO_Setpoints[L_i] := 22.0; END_IF;
    END_FOR;
ELSE
    VO_Heating_Active := FALSE;
END_IF;

L_Current_Slot := (VI_Time_Index / 600000) MOD 1008; // Слот каждые 10 минут

IF VI_Mode_Record THEN
    // Запись текущего состояния в слот
    L_History[L_Current_Slot] := 0;
    FOR L_i := 1 TO 16 DO
        IF VI_Light_Inputs[L_i] THEN
            L_History[L_Current_Slot] := L_History[L_Current_Slot] OR SHL(WORD#1, L_i-1);
        END_IF;
    END_FOR;
ELSE
    // Воспроизведение из слота
    FOR L_i := 1 TO 16 DO
        VO_Light_Outputs[L_i] := (L_History[L_Current_Slot] AND SHL(WORD#1, L_i-1)) <> 0;
    END_FOR;
END_IF;

IF VI_Enabled THEN
    IF VI_Use_Playback THEN
        fbPlayback(VI_Mode_Record := FALSE, VI_Time_Index := VI_System_Time MOD 604800000, VO_Light_Outputs => VO_Light_States);
    ELSE
        // Старая логика случайной симуляции
        VO_Light_States[1] := (VI_System_Time MOD 100000 > 50000);
    END_IF;
END_IF;

L_seed := (C_LCG_MULTIPLIER * L_seed) + C_LCG_INCREMENT;

IF VI_max > VI_min THEN
        L_range := VI_max - VI_min;
        // Используем LREAL для точности и исключения выхода за границу
        L_rand_factor := TO_LREAL(L_seed) / C_LCG_MODULUS;
        Random_Int_Range := VI_min + TO_UDINT(L_rand_factor * TO_LREAL(L_range + 1));

        // Финальная защита от переполнения
        IF Random_Int_Range > VI_max THEN
            Random_Int_Range := VI_max;
        END_IF;
    ELSE
        Random_Int_Range := VI_min;
    END_IF;

IF VI_IsActivePLC AND (VI_Activate_Request <> VO_Current_Scenario) THEN
    // Логика переключения сценариев
    VO_Current_Scenario := VI_Activate_Request;

    CASE VO_Current_Scenario OF
        E_SCENARIO_TYPE.SCENARIO_NONE:
            VO_Status_Msg := 'Сценарии отключены';
        E_SCENARIO_TYPE.SCENARIO_AWAY:
            VO_Status_Msg := 'Активирован сценарий: Вне дома (Охрана + Энергосбережение)';
        E_SCENARIO_TYPE.SCENARIO_SLEEP:
            VO_Status_Msg := 'Активирован сценарий: Сон (Ночное освещение + Климат)';
        E_SCENARIO_TYPE.SCENARIO_PRESENCE:
            VO_Status_Msg := 'Активирован сценарий: Имитация присутствия';
    END_CASE;
END_IF;

VO_Alarm_Active := CheckPerimeter();

IF VO_Alarm_Active THEN
    VO_Status_Msg := 'ТРЕВОГА: НАРУШЕН ПЕРИМЕТР';
ELSE
    VO_Status_Msg := 'Периметр в норме';
END_IF;

CheckPerimeter := FALSE;
// Проверка окон
FOR L_i := 1 TO 20 DO
    IF VI_Assigned_DoorWindow_Open[L_i] THEN
        CheckPerimeter := TRUE;
        RETURN;
    END_IF;
END_FOR;
// Проверка стекол
FOR L_i := 1 TO 12 DO
    IF VI_Assigned_GlassBreak[L_i] THEN
        CheckPerimeter := TRUE;
        RETURN;
    END_IF;
END_FOR;

L_Trigger_Count := 0;
FOR L_i := 1 TO 15 DO
    IF VI_Sensors_Open[L_i] OR VI_Sensors_Glass[L_i] THEN
        L_Trigger_Count := L_Trigger_Count + 1;
    END_IF;
END_FOR;
IF VI_Grouped_2F THEN L_Trigger_Count := L_Trigger_Count + 1; END_IF;

// Логика п. 3.3: Комбинированные события (>=2 датчиков за 10 сек)
IF L_Trigger_Count >= 2 THEN
    IF (VI_System_Time - L_Last_Trigger_Time) < 10000 THEN
        VO_Alarm_Level := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
        VO_Alarm_Active := TRUE;
    END_IF;
    L_Last_Trigger_Time := VI_System_Time;
END_IF;

// 1. Мониторинг датчиков
L_Any_Sensor_Open := VI_Group_2F_Open;
FOR L_i := 1 TO 15 DO IF VI_Opening_Sensors[L_i] THEN L_Any_Sensor_Open := TRUE; EXIT; END_IF; END_FOR;

L_Any_Glass_Broken := VI_Group_2F_Glass;
FOR L_i := 1 TO 15 DO IF VI_GlassBreak_Sensors[L_i] THEN L_Any_Glass_Broken := TRUE; EXIT; END_IF; END_FOR;

// ТЗ 3.3: Подсчет срабатываний за 10с
L_Trigger_Timer(IN := L_Trigger_Count > 0, PT := T#10s);
IF L_Trigger_Timer.Q THEN L_Trigger_Count := 0; END_IF;

FOR L_i := 1 TO 15 DO
    IF VI_Opening_Sensors[L_i] AND NOT L_Last_Sensors[L_i] THEN L_Trigger_Count := L_Trigger_Count + 1; END_IF;
    L_Last_Sensors[L_i] := VI_Opening_Sensors[L_i];

    IF VI_GlassBreak_Sensors[L_i] AND NOT L_Last_Sensors[15 + L_i] THEN L_Trigger_Count := L_Trigger_Count + 1; END_IF;
    L_Last_Sensors[15 + L_i] := VI_GlassBreak_Sensors[L_i];
END_FOR;
// Групповые датчики тоже участвуют в подсчете
IF VI_Group_2F_Open AND NOT L_Last_Sensors[31] THEN L_Trigger_Count := L_Trigger_Count + 1; END_IF;
L_Last_Sensors[31] := VI_Group_2F_Open;
IF VI_Group_2F_Glass AND NOT L_Last_Sensors[32] THEN L_Trigger_Count := L_Trigger_Count + 1; END_IF;
L_Last_Sensors[32] := VI_Group_2F_Glass;

// ТЗ 3.8: Снижение порога на 20% (увеличиваем чувствительность)
L_Glass_Threshold_Multiplier := SEL(VI_Acknowledge_Open_Windows, 1.0, 0.8);

// 2. Логика состояний
CASE L_State OF
    0: // Снято с охраны
        VO_Armed := FALSE; VO_Alarm_Active := FALSE; VO_Entry_Delay_Active := FALSE; VO_Long_Away_Req := FALSE;
        IF VI_PIN_Submit AND VI_PIN_Input = VI_Config.PIN_Code THEN
            IF NOT L_Any_Sensor_Open OR VI_Acknowledge_Open_Windows THEN
                IF VI_Config.Two_Stage_Mode THEN
                    L_State := 4; L_Confirm_Start_Time := VI_System_Time_MS;
                    VO_Status_Msg := 'Ожидание второго этапа подтверждения';
                ELSE
                    L_State := 1; L_Away_Start_Time := VI_System_Time_MS; L_Attempts := 0;
                    VO_Status_Msg := 'Система поставлена на охрану';
                END_IF;
            ELSE
                VO_Status_Msg := 'Ошибка: Обнаружены открытые окна/двери';
            END_IF;
        END_IF;

    4: // Ожидание второго этапа (ТЗ 3.4)
        IF (VI_System_Time_MS - L_Confirm_Start_Time) / 1000 >= VI_Config.Confirmation_Timeout_S THEN
            L_State := 0; VO_Status_Msg := 'Таймаут подтверждения постановки';
        ELSIF VI_PIN_Submit AND VI_PIN_Input = VI_Config.PIN_Code THEN
             L_State := 1; L_Away_Start_Time := VI_System_Time_MS; L_Attempts := 0;
             VO_Status_Msg := 'Система поставлена на охрану (2 этапа)';
        END_IF;

    1: // На охране
        VO_Armed := TRUE;
        // ТЗ 3.3: Немедленная тревога если >=2 датчика за 10с
        IF L_Trigger_Count >= 2 THEN
            L_State := 3;
        ELSIF L_Any_Sensor_Open OR L_Any_Glass_Broken THEN
            L_State := 2; L_Entry_Start_Time := VI_System_Time_MS;
        END_IF;

    2: // Задержка входа (ТЗ 3.3)
        VO_Entry_Delay_Active := TRUE;
        VO_Time_To_Alarm_S := TO_UINT(VI_Config.Entry_Delay_S - (VI_System_Time_MS - L_Entry_Start_Time) / 1000);
        IF VI_PIN_Submit THEN
            IF VI_PIN_Input = VI_Config.PIN_Code THEN L_State := 0; VO_Status_Msg := 'Система снята с охраны';
            ELSE
                L_Attempts := L_Attempts + 1;
                IF L_Attempts >= VI_Config.Max_Attempts THEN L_State := 3; END_IF;
            END_IF;
        END_IF;
        IF (VI_System_Time_MS - L_Entry_Start_Time) / 1000 >= VI_Config.Entry_Delay_S THEN L_State := 3; END_IF;

    3: // Тревога
        VO_Alarm_Active := TRUE;
        VO_Long_Away_Req := TRUE; // ТЗ 3.6: При тревоге -> долгосрочный отъезд
        VO_Status_Msg := 'ТРЕВОГА: НАРУШЕНИЕ ПЕРИМЕТРА';
        IF VI_PIN_Submit AND VI_PIN_Input = VI_Config.PIN_Code THEN L_State := 0; VO_Status_Msg := 'Тревога сброшена'; END_IF;
END_CASE;

// 3. Уровни отъезда (ТЗ 3.5)
IF L_State <> 0 THEN
    L_Last_Trigger_Time := (VI_System_Time_MS - L_Away_Start_Time) / 3600000; // Часы
    IF L_Last_Trigger_Time < 2 THEN VO_Away_Level := 1;
    ELSIF L_Last_Trigger_Time < 72 THEN VO_Away_Level := 2;
    ELSE VO_Away_Level := 3; END_IF;
ELSE VO_Away_Level := 0; END_IF;

// 4. Интеграция с освещением (ТЗ 3.9)
IF (VI_Outdoor_Lux < 50.0 OR (TOD_TO_UDINT(UDINT_TO_TOD(VI_System_Time_MS)) > 64800000 OR TOD_TO_UDINT(UDINT_TO_TOD(VI_System_Time_MS)) < 28800000)) THEN
    IF VI_Motion_Corridor OR (L_State = 2) THEN VO_Light_Corridor := TRUE; VO_Light_Stairs_Dim := 30;
    ELSE VO_Light_Corridor := FALSE; VO_Light_Stairs_Dim := 0; END_IF;
END_IF;

FOR L_i := 1 TO 20 DO
    // ПЛК A берет четные, ПЛК B - нечетные
    IF (VI_Local_PLC_ID = 1 AND (L_i MOD 2 = 0)) OR
       (VI_Local_PLC_ID = 2 AND (L_i MOD 2 <> 0)) THEN
        VO_Assigned_Sensors[L_i] := VI_Raw_Sensors[L_i];
    END_IF;
END_FOR;

IF NOT VI_Enabled THEN L_Active := FALSE; RETURN; END_IF;

// ТЗ 7.2: Временные окна (07-10, 18-23, 01-04)
L_Current_TOD := UDINT_TO_TOD(VI_System_Time_MS MOD 86400000);
L_In_Window := (L_Current_TOD >= TOD#07:00 AND L_Current_TOD <= TOD#10:00) OR
               (L_Current_TOD >= TOD#18:00 AND L_Current_TOD <= TOD#23:00) OR
               (L_Current_TOD >= TOD#01:00 AND L_Current_TOD <= TOD#04:00);

IF NOT L_In_Window THEN L_Active := FALSE; FOR L_i := 1 TO 16 DO VO_Light_States[L_i] := FALSE; END_FOR; RETURN; END_IF;

// Логика случайных событий
IF NOT L_Active THEN
    IF (L_Rand.Random_Int_Range(0, 1000) < TO_UDINT(VI_Intensity * 10.0)) THEN
        L_Active := TRUE; L_Last_Event_Time := VI_System_Time_MS;

        // ТЗ 7.2: Распределение 70/30
        IF L_Rand.Random_Int_Range(0, 100) < 70 THEN
            L_Event_Duration := L_Rand.Random_Int_Range(300000, 900000); // 5-15 мин (70%)
        ELSE
            L_Event_Duration := L_Rand.Random_Int_Range(900001, 2700000); // 15-45 мин (30%)
        END_IF;

        FOR L_i := 1 TO 16 DO VO_Light_States[L_i] := (L_Rand.Random_Int_Range(0, 10) > 7); END_FOR;
    END_IF;
ELSE
    IF (VI_System_Time_MS - L_Last_Event_Time) >= L_Event_Duration THEN
        L_Active := FALSE; FOR L_i := 1 TO 16 DO VO_Light_States[L_i] := FALSE; END_FOR;
    END_IF;
END_IF;

FOR L_i := 1 TO 6 DO
    IF VI_Sensors[L_i] THEN
        IF NOT L_Verifying[L_i] THEN
            L_Verifying[L_i] := TRUE;
            L_Verify_Start[L_i] := VI_System_Time;
        ELSIF (VI_System_Time - L_Verify_Start[L_i]) > 30000 THEN
            VO_Fire_Alarm := TRUE;
        END_IF;
    ELSE
        L_Verifying[L_i] := FALSE;
    END_IF;
END_FOR;

CASE L_State OF
    0: // Ожидание запроса
        IF VI_Send_Request THEN
            VO_Done := FALSE;
            VO_Error := FALSE;
            L_State := 1;
        END_IF;

    1: // Отправка AT+CMGF=1 (Установка текстового режима)
        L_AT_Command := 'AT+CMGF=1$R';
        L_State := 2;
        L_Timer(IN := TRUE, PT := T#500ms);

    2: // Ожидание ответа OK и отправка номера
        L_Timer(IN := TRUE);
        IF L_Timer.Q THEN
            L_Timer(IN := FALSE);
            L_AT_Command := CONCAT('AT+CMGS="', CONCAT(VI_Phone, '"$R'));
            L_State := 3;
            L_Timer(IN := TRUE, PT := T#500ms);
        END_IF;

    3: // Отправка текста сообщения и символа Ctrl+Z (ASCII 26)
        L_Timer(IN := TRUE);
        IF L_Timer.Q THEN
            L_Timer(IN := FALSE);
            L_AT_Command := CONCAT(VI_Text, '$1A'); // $1A - это Ctrl+Z в CODESYS
            L_State := 4;
            L_Timer(IN := TRUE, PT := T#2s);
        END_IF;

    4: // Завершение
        L_Timer(IN := TRUE);
        IF L_Timer.Q THEN
            L_Timer(IN := FALSE);
            VO_Done := TRUE;
            L_State := 0;
        END_IF;
END_CASE;

CASE VI_Command OF
    1: // Save
        L_Saved_Heating := VI_Heating_Config;
        VO_Done := TRUE;

    2: // Restore (Плавное восстановление за 60с - ТЗ 3.6)
        IF NOT L_Restoring THEN
            L_Restoring := TRUE;
            L_Restore_Start_Time := VI_System_Time_MS;
        END_IF;

        IF (VI_System_Time_MS - L_Restore_Start_Time) >= 60000 THEN
            VO_Heating_Config := L_Saved_Heating;
            L_Restoring := FALSE;
            VO_Done := TRUE;
        ELSE
            // Здесь можно реализовать интерполяцию, но для простоты восстановим в конце
            VO_Done := FALSE;
        END_IF;
END_CASE;

IF VI_Save_Req THEN
    L_Buffer[L_Idx] := VI_Snapshot;
    L_Buffer[L_Idx].timestamp_ms := VI_System_Time;
    VO_Last_ID := VI_System_Time;
    L_Idx := (L_Idx + 1) MOD 10;
END_IF;

// Исправленное копирование структуры через указатель
IF VI_Snapshot_Ptr <> 0 THEN
    L_byte_ptr := ADR(VI_Snapshot_Ptr^);

    CASE L_state OF
        1: // СОХРАНЕНИЕ (SAVE)
            IF L_step = 0 THEN
                // Копируем всю структуру байт за байтом в буфер NVRAM
                // Используем SIZEOF(ST_State_Snapshot), чтобы не выйти за границы структуры
                FOR L_i := 0 TO (SIZEOF(ST_State_Snapshot) - 1) DO
                    IF L_i < C_RECORD_SIZE THEN
                        L_temp_buffer[L_i + 1] := L_byte_ptr[TO_INT(L_i)];
                    END_IF;
                END_FOR;
                L_step := 1;
            END_IF;

        2: // ЗАГРУЗКА (LOAD)
            IF L_step = 2 THEN
                // Копируем из буфера обратно в структуру
                FOR L_i := 0 TO (SIZEOF(ST_State_Snapshot) - 1) DO
                    IF L_i < C_RECORD_SIZE THEN
                        L_byte_ptr[TO_INT(L_i)] := L_temp_buffer[L_i + 1];
                    END_IF;
                END_FOR;
                VO_Done := TRUE;
                L_state := 0;
            END_IF;
    END_CASE;
END_IF;

// 1. Накопление почасовой истории (ТЗ 12.1)
IF (VI_System_Time_MS - L_Last_Hour_Time) >= 3600000 OR L_Last_Hour_Time = 0 THEN
    L_Last_Hour_Time := VI_System_Time_MS;
    L_History[L_Idx] := VI_Value;
    L_Idx := (L_Idx MOD 168) + 1;
    IF L_Count < 168 THEN L_Count := L_Count + 1; END_IF;
END_IF;

// 2. Расчет среднего за 7 дней
L_Sum := 0.0;
IF L_Count > 0 THEN
    FOR L_i := 1 TO L_Count DO L_Sum := L_Sum + L_History[L_i]; END_FOR;
    VO_Average_7D := L_Sum / TO_REAL(L_Count);
END_IF;

// 3. Детекция аномалий и метка диагностики (ТЗ 12.1)
IF VO_Average_7D > 0.0 THEN
    VO_Anomaly_Detected := (ABS(VI_Value - VO_Average_7D) / VO_Average_7D * 100.0) > VI_Threshold_Percent;
    VO_Diag_Label := VO_Anomaly_Detected; // Метка ставится при отклонении
END_IF;

CASE L_State OF
    0: 
        IF VI_Start_Auth THEN
            L_State := 1;
            L_Start_Timestamp := VI_System_Time_MS;
            VO_Busy := TRUE;
        END_IF;
    1:
        IF VI_RFID_Tag <> '' THEN
            L_State := 2;
        ELSIF (VI_System_Time_MS - L_Start_Timestamp) > 30000 THEN
            L_State := 0;
            VO_Auth_Failed := TRUE;
            VO_Busy := FALSE;
        END_IF;
    2:
        IF VI_TOTP_Code <> '' THEN
            VO_Auth_Passed := TRUE;
            L_State := 0;
            VO_Busy := FALSE;
        END_IF;
END_CASE;

// Сброс приоритетов перед циклом
FOR L_i := 1 TO 100 DO L_Applied_Priority[L_i] := 0; END_FOR;

FOR L_i := 1 TO 10 DO
    IF VI_Rules[L_i].Enabled THEN
        L_Condition_Met := FALSE;

        // Вычисление условия (ТЗ 7.4)
        CASE VI_Rules[L_i].Condition_Type OF
            1: // Температура уличная
                L_Val := VI_System_State.Outdoor_Temp;
            2: // Температура пола (Зона 1)
                L_Val := VI_System_State.Floor_Temps[1];
            3: // CO2 (Зона 1)
                L_Val := VI_System_State.CO2[1];
            4: // Охрана
                L_Val := SEL(VI_System_State.Security_Armed, 0.0, 1.0);
        END_CASE;

        CASE VI_Rules[L_i].Condition_Op OF
            1: L_Condition_Met := (L_Val > VI_Rules[L_i].Condition_Value);
            2: L_Condition_Met := (L_Val < VI_Rules[L_i].Condition_Value);
            3: L_Condition_Met := (ABS(L_Val - VI_Rules[L_i].Condition_Value) < 0.01);
        END_CASE;

        // Выполнение действия с учетом приоритета (ТЗ 7.4)
        IF L_Condition_Met THEN
             // Проверяем, не выполнялось ли уже действие для этого Target_ID с более высоким приоритетом
             IF VI_Rules[L_i].Action_Target_ID > 0 AND VI_Rules[L_i].Action_Target_ID <= 100 THEN
                 IF VI_Rules[L_i].Priority >= L_Applied_Priority[VI_Rules[L_i].Action_Target_ID] THEN
                     VO_Actions[L_i].Active := TRUE;
                     VO_Actions[L_i].Target_ID := VI_Rules[L_i].Action_Target_ID;
                     VO_Actions[L_i].Value := VI_Rules[L_i].Action_Value;
                     L_Applied_Priority[VI_Rules[L_i].Action_Target_ID] := VI_Rules[L_i].Priority;
                 ELSE
                     VO_Actions[L_i].Active := FALSE; // Игнорируем из-за низкого приоритета
                 END_IF;
             END_IF;
        ELSE
             VO_Actions[L_i].Active := FALSE;
        END_IF;
    END_IF;
END_FOR;

IF VI_Start_Test AND NOT VO_Test_Active THEN
    VO_Test_Active := TRUE;
    L_Start_Timestamp := VI_System_Time;
    L_Peak_Current := 0.0;
    L_Reaction_Time := 0;
END_IF;

IF VO_Test_Active THEN
    IF VI_Current_A > L_Peak_Current THEN L_Peak_Current := VI_Current_A; END_IF;

    // Определение времени реакции (ток превысил 100мА)
    IF L_Reaction_Time = 0 AND VI_Current_A > 100.0 THEN
        L_Reaction_Time := VI_System_Time - L_Start_Timestamp;
    END_IF;

    IF (VI_System_Time - L_Start_Timestamp) > 15000 THEN
        VO_Test_Active := FALSE;

        // ТЗ 12.2: Контроль отклонения > 30% от номинала
        VO_Deviation_Percent := ABS(L_Peak_Current - VI_Config.Nominal_Current) / VI_Config.Nominal_Current * 100.0;

        VO_Test_Passed := (VO_Deviation_Percent <= 30.0) AND (L_Reaction_Time < 5000);

        IF NOT VO_Test_Passed THEN
            VO_Error_Code := 16#E122; // Valve Test Failed
        END_IF;
    END_IF;
END_IF;

// 1. Определение режима
L_Current_Time := UDINT_TO_TOD(VI_System_Time_MS MOD 86400000);
L_Is_Night := (L_Current_Time >= VI_Config.Night_Mode_Start OR L_Current_Time <= VI_Config.Night_Mode_End);

// Поиск максимумов
L_Max_CO2 := 0.0;
FOR L_i := 1 TO 8 DO
    IF VI_CO2[L_i] > L_Max_CO2 THEN L_Max_CO2 := VI_CO2[L_i]; END_IF;
END_FOR;

L_Max_Hum := 0.0;
FOR L_i := 1 TO 8 DO
    IF VI_Humidity[L_i] > L_Max_Hum THEN L_Max_Hum := VI_Humidity[L_i]; END_IF;
END_FOR;

// Выбор режима (ТЗ 6.3)
IF VI_Gas_Alarm OR VI_Fire_Alarm OR VI_Flood_Alarm THEN
    L_Mode := 3; // Аварийный
    L_Base_Speed := 100.0;
ELSIF L_Max_CO2 > VI_Config.CO2_Threshold OR L_Max_Hum > VI_Config.Humidity_Threshold THEN
    L_Mode := 2; // Интенсив
    L_Base_Speed := 70.0;
ELSIF L_Is_Night THEN
    L_Mode := 0; // Эконом
    L_Base_Speed := 20.0;
ELSE
    L_Mode := 1; // Стандарт
    L_Base_Speed := 40.0;
END_IF;

// 2. Управление вентиляторами
FOR L_i := 1 TO 3 DO
    VO_Supply_Fans[L_i] := L_Base_Speed;

    // ТЗ 5.4: CO -> приток 80%
    IF VI_Supply_80_Req THEN VO_Supply_Fans[L_i] := 80.0; END_IF;

    // ТЗ 6.4: Метан >20% -> приток 100%
    IF VI_Supply_100_Req THEN VO_Supply_Fans[L_i] := 100.0; END_IF;

    // ТЗ 5.1: ПВ-3 форсирован при 10% LEL
    IF L_i = 3 AND VI_PV3_Boost THEN VO_Supply_Fans[L_i] := 100.0; END_IF;

    // Интеграция с безопасностью (ТЗ 6.4): При пожаре приток ОТКЛЮЧАЕТСЯ
    IF VI_Fire_Alarm THEN
        VO_Supply_Fans[L_i] := 0.0;
    END_IF;
END_FOR;

FOR L_i := 1 TO 5 DO
    VO_Exhaust_Fans[L_i] := L_Base_Speed;

    // ТЗ 4.0: Интеграция с мокрыми зонами (вытяжки 4-5)
    IF L_i >= 4 THEN
        L_Wet_Zone_Timers[L_i-3](IN := VI_Wet_Zone_Lights[L_i-3], PT := T#7m); // 7 мин пост-вентиляция
        IF L_Wet_Zone_Timers[L_i-3].Q THEN
            VO_Exhaust_Fans[L_i] := MAX(VO_Exhaust_Fans[L_i], 60.0); // Форсируем вытяжку
        END_IF;
    END_IF;

    // ТЗ 6.4: Пожар -> вытяжка 100%
    IF VI_Exhaust_100_Req THEN VO_Exhaust_Fans[L_i] := 100.0; END_IF;
END_FOR;

// 3. Статус
FOR L_i := 1 TO 3 DO
    VO_Status[L_i].Enabled := VI_IsActivePLC;
    VO_Status[L_i].Speed_Percent := VO_Supply_Fans[L_i];
    VO_Status[L_i].Mode := L_Mode;
END_FOR;

// 1. Определение протечки по зонам (ТЗ 4.1)
L_Zone1_Alarm := VI_Sensors[1] OR VI_Sensors[2] OR VI_Sensors[3];
L_Zone2_Alarm := VI_Sensors[4] OR VI_Sensors[5];
L_Zone3_Alarm := VI_Sensors[6] OR VI_Sensors[7];
VO_Flood_Alarm := L_Zone1_Alarm OR L_Zone2_Alarm OR L_Zone3_Alarm;

// 2. Управление клапанами (ТЗ 4.2, 4.3)
// ТЗ 4.3: НЗ клапаны закрываются при потере питания (автоматически физически)
// Но мы должны отразить это в логике и статусе
VO_Valve_35_Close := L_Zone1_Alarm OR NOT VI_Power_OK;
VO_Valve_36_Close := L_Zone2_Alarm OR L_Zone3_Alarm OR NOT VI_Power_OK;

// Диагностика по току (ТЗ 4.3)
L_Valve_35_Error := (VO_Valve_35_Close AND VI_Valve_35_Current < 50.0) OR (NOT VO_Valve_35_Close AND VI_Valve_35_Current > VI_Config.Current_Threshold_MA);
L_Valve_36_Error := (VO_Valve_36_Close AND VI_Valve_36_Current < 50.0) OR (NOT VO_Valve_36_Close AND VI_Valve_36_Current > VI_Config.Current_Threshold_MA);

// Эскалация приоритета (ТЗ 4.3)
IF VO_Flood_Alarm THEN
    VO_Alert_Priority := 2; // Normal
    IF L_Valve_35_Error OR L_Valve_36_Error THEN
        VO_Alert_Priority := 3; // Critical (НО клапан не закрылся или обрыв)
    END_IF;
ELSE
    VO_Alert_Priority := 1; // Low
END_IF;

// 3. Экстренное открытие (ТЗ 4.4)
L_Day_Timer(IN := TRUE, PT := T#24h);
IF L_Day_Timer.Q THEN L_Emergency_Count := 0; L_Day_Timer(IN := FALSE); END_IF;

IF VI_Emergency_Open_Req > 0 AND VI_Emergency_Open_Req <> L_Last_Req AND L_Emergency_Count < 3 THEN
    IF VI_Config.Emergency_Two_Stage_Enabled AND NOT L_Confirm_Wait THEN
        L_Confirm_Wait := TRUE;
        L_Confirm_Timer(IN := TRUE, PT := T#30s);
        VO_Status_Msg := 'ОЖИДАНИЕ ПОДТВЕРЖДЕНИЯ ЭКСТРЕННОГО ОТКРЫТИЯ';
    ELSIF (VI_Config.Emergency_Two_Stage_Enabled AND VI_Two_Stage_Confirm) OR NOT VI_Config.Emergency_Two_Stage_Enabled THEN
        L_Emergency_Count := L_Emergency_Count + 1;
        L_Last_Req := VI_Emergency_Open_Req;
        L_Emergency_Timer(IN := TRUE, PT := TO_TIME(TO_UDINT(VI_Emergency_Open_Req) * 60000));
        L_Confirm_Wait := FALSE; L_Confirm_Timer(IN := FALSE);
    END_IF;
END_IF;

L_Confirm_Timer(IN := L_Confirm_Wait);
IF L_Confirm_Timer.Q THEN L_Confirm_Wait := FALSE; L_Confirm_Timer(IN := FALSE); END_IF;

IF L_Emergency_Timer.IN AND NOT L_Emergency_Timer.Q THEN
    VO_Valve_35_Close := FALSE; VO_Valve_36_Close := FALSE;
    VO_Status_Msg := 'ЭКСТРЕННОЕ ОТКРЫТИЕ ВОДЫ';
ELSE
    L_Emergency_Timer(IN := FALSE);
    IF VI_Emergency_Open_Req = 0 THEN L_Last_Req := 0; END_IF;
END_IF;

IF VO_Flood_Alarm AND NOT L_Emergency_Timer.IN AND NOT L_Confirm_Wait THEN VO_Status_Msg := 'ОБНАРУЖЕНА ПРОТЕЧКА ВОДЫ'; END_IF;
IF NOT VI_Power_OK THEN VO_Status_Msg := 'ВНИМАНИЕ: ОТСУТСТВИЕ ПИТАНИЯ КЛАПАНОВ'; END_IF;

// Логика диагностики (п. 4.3 ТЗ)
IF L_Moving THEN
    IF (VI_System_Time - L_Move_Start_Time) > 10000 THEN // Таймаут 10 сек
        VO_Status := 3; // Ошибка
        L_Moving := FALSE;
    ELSIF (L_Target_State = TRUE AND VI_Limit_Closed) OR (L_Target_State = FALSE AND VI_Limit_Open) THEN
        VO_Status := SEL(L_Target_State, 0, 1);
        L_Moving := FALSE;
    ELSE
        VO_Status := 2; // Moving
    END_IF;
END_IF;

IF VI_IsActivePLC OR VI_Force THEN
    VO_Valve_Open_Cmd := TRUE;
    VO_Valve_Close_Cmd := FALSE;
    L_Moving := TRUE;
    L_Target_State := FALSE;
    L_Move_Start_Time := VI_System_Time;
    OpenValve := TRUE;
ELSE
    OpenValve := FALSE;
END_IF;

IF VI_IsActivePLC OR VI_Force THEN
    VO_Valve_Open_Cmd := FALSE;
    VO_Valve_Close_Cmd := TRUE;
    L_Moving := TRUE;
    L_Target_State := TRUE;
    L_Move_Start_Time := VI_System_Time;
    CloseValve := TRUE;
ELSE
    CloseValve := FALSE;
END_IF;

IF VI_Op = 'ADMIN' THEN
    // Если 2FA включена, проверяем флаг прохождения второго фактора
    IF GVL_HMI_Config.G_HMI_Admin_2FA_Enabled THEN
        CheckAccess := GVL_HMI_Config.G_HMI_Current_Operator_Factor2_Done;
    ELSE
        CheckAccess := TRUE;
    END_IF;
ELSIF VI_Op = 'SERVICE' AND VI_Req_Level <= 3 THEN
    CheckAccess := TRUE;
ELSE
    CheckAccess := FALSE;
END_IF;

// 0. Обновление системного времени
GVL_Vars.G_System_Time_MS := GVL_Vars.G_System_Time_MS + 10; 

// 1. Логика резервирования (ТЗ 11.1)
fbHeartbeat(
    VI_Local_ID := GVL_Vars.G_Local_PLC_ID,
    VI_System_Time := GVL_Vars.G_System_Time_MS,
    VI_Remote_Pulse := GVL_Vars.G_Remote_PLC_Pulse,
    VO_Is_Active => L_Is_Active
);
GVL_Vars.G_Active_PLC_ID := SEL(L_Is_Active, 0, GVL_Vars.G_Local_PLC_ID);

// 2. Инициализация и Бэкап (ТЗ 16.2)
L_Current_TOD := UDINT_TO_TOD(GVL_Vars.G_System_Time_MS MOD 86400000);
IF L_First_Cycle THEN
    L_First_Cycle := FALSE;
    fbNVRAM(VI_Command := 2, VI_RecordIndex := 1, VI_DataPtr := ADR(GVL_Vars.G_HMI_Gas_Config), VI_DataSize := SIZEOF(GVL_Vars.G_HMI_Gas_Config));
END_IF;

// Ежесуточный бэкап в 03:00 (ТЗ 16.2: Ротация 7 копий)
IF L_Current_TOD >= TOD#03:00 AND L_Current_TOD <= TOD#03:00:01 THEN
    fbNVRAM(VI_Command := 1, VI_RecordIndex := L_Backup_Day, VI_DataPtr := ADR(GVL_Vars.G_HMI_Gas_Config), VI_DataSize := SIZEOF(GVL_Vars.G_HMI_Gas_Config));
    L_Backup_Day := (L_Backup_Day MOD 7) + 1;
END_IF;

// 3. ТЗ 8.2: Параллельная обработка датчиков
FOR L_i := 1 TO 2 DO 
    L_Methane_LEL_Real[L_i] := GVL_IO.AI_Methane_LEL[L_i].rValue; 
END_FOR;
FOR L_i := 1 TO 5 DO 
    L_Manifold_Temps_Supply_Real[L_i] := GVL_IO.AI_Manifold_Temps_Supply[L_i].rValue; 
    L_Manifold_Temps_Return_Real[L_i] := TO_REAL(GVL_IO.AI_Manifold_Temps_Return[L_i]) / 10.0;
    L_Manifold_Pressures_Real[L_i] := TO_REAL(GVL_IO.AI_Manifold_Pressures[L_i]) / 100.0; // 0-10V -> 0-10.0 bar
    L_Manifold_Currents_Real[L_i] := TO_REAL(GVL_IO.AI_Manifold_Currents[L_i]) / 100.0; // 4-20mA -> 4.0-20.0 mA
END_FOR;

FOR L_i := 1 TO 15 DO
    // ПЛК A (ID=1) обрабатывает нечетные, ПЛК B (ID=2) - четные
    IF (GVL_Vars.G_Local_PLC_ID = 1 AND (L_i MOD 2 <> 0)) OR (GVL_Vars.G_Local_PLC_ID = 2 AND (L_i MOD 2 = 0)) THEN
        L_Opening_Sensors[L_i] := GVL_IO.DI_Security_Open[L_i];
        L_GlassBreak_Sensors[L_i] := GVL_IO.DI_Security_Glass[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO 12 DO
    IF (GVL_Vars.G_Local_PLC_ID = 1 AND (L_i MOD 2 <> 0)) OR (GVL_Vars.G_Local_PLC_ID = 2 AND (L_i MOD 2 = 0)) THEN
        L_Flood_Sensors[L_i] := GVL_IO.DI_Flood_Sensors[L_i];
    END_IF;
END_FOR;

    // 4. Сбор состояния
    L_System_State.Outdoor_Temp := GVL_IO.AI_Temp_Outdoor.rValue;
    FOR L_i := 1 TO 16 DO 
        L_System_State.Floor_Temps[L_i] := GVL_IO.AI_Floor_Temps[L_i]; 
        L_System_State.Indoor_Temp[L_i] := GVL_IO.AI_Room_Temps[L_i];
        L_System_State.CO2[MIN(L_i, 8)] := 400.0; 
        L_System_State.Humidity[MIN(L_i, 8)] := 45.0; 
    END_FOR;
    L_System_State.Security_Armed := GVL_Vars.G_Security_Armed;
    L_System_State.Flood_Alarm := GVL_Vars.G_Flood_Alarm_Active;
    L_System_State.Gas_Alarm := GVL_Vars.G_Gas_Alarm_Active;
    L_System_State.Fire_Alarm := GVL_Vars.G_Fire_Alarm_Active;

    // 5. Выполнение системной логики
    fbGasSmoke(
        VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
        VI_IsActivePLC := L_Is_Active,
        VI_Methane_LEL := L_Methane_LEL_Real,
        VI_CO_PPM := GVL_IO.AI_CO_PPM,
        VI_Smoke_Sensors := GVL_IO.DI_Smoke_Sensors,
        VI_Mute_Request := GVL_Vars.G_HMI_Mute_Alarm,
        VO_Gas_Alarm => GVL_Vars.G_Gas_Alarm_Active,
        VO_Fire_Alarm => GVL_Vars.G_Fire_Alarm_Active,
        VO_Gas_Valve_Close => GVL_IO.DO_Gas_Valve_Close
    );

    // ТЗ 3.6: При тревоге -> долгосрочный отъезд
    IF fbSecurity.VO_Long_Away_Req THEN
        GVL_Vars.G_Current_Scenario := E_SCENARIO_TYPE.SCENARIO_AWAY;
    END_IF;

    fbWater(
        VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
        VI_IsActivePLC := L_Is_Active,
        VI_Sensors := L_Flood_Sensors,
        VI_Valve_35_Current := GVL_IO.AI_Water_Valve_35_Current,
        VI_Valve_36_Current := GVL_IO.AI_Water_Valve_36_Current,
        VI_Config := GVL_Vars.G_Flood_Config,
        VI_Power_OK := GVL_IO.DI_Power_OK,
        VO_Flood_Alarm => GVL_Vars.G_Flood_Alarm_Active,
        VO_Valve_35_Close => GVL_IO.DO_Water_Valve_35_Close,
        VO_Valve_36_Close => GVL_IO.DO_Water_Valve_36_Close
    );

    fbHeating(
        VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
        VI_IsActivePLC := L_Is_Active AND NOT fbGasSmoke.VO_Boiler_Stop,
        VI_Outdoor_Temp := L_System_State.Outdoor_Temp,
        VI_Floor_Temps := GVL_IO.AI_Floor_Temps,
        VI_Room_Temps := GVL_IO.AI_Room_Temps,
        VI_Config := GVL_Vars.G_Heating_Config,
        VI_Manifold_Temps_Supply := L_Manifold_Temps_Supply_Real,
        VI_Manifold_Temps_Return := L_Manifold_Temps_Return_Real,
        VI_Manifold_Pressures := L_Manifold_Pressures_Real,
        VI_Manifold_Currents := L_Manifold_Currents_Real,
        VI_Boiler_Flame_Status := GVL_IO.AI_Boiler_Flame_Status,
        VI_Maintenance_Zones := GVL_Vars.G_Maintenance_Zones,
        VI_Maintenance_Manifolds := GVL_Vars.G_Maintenance_Manifolds,
        VO_Manifold_Pumps => GVL_IO.DO_Manifold_Pumps,
        VO_Zone_Valves => GVL_IO.DO_Zone_Valves,
        VO_Boiler_Enable => GVL_IO.DO_Boiler_Enable
    );
    // Конверсия выходов для Modbus
    FOR L_i := 1 TO 5 DO GVL_IO.AO_Manifold_Valves[L_i] := TO_UINT(fbHeating.VO_Manifold_Valves[L_i] * 10.0); END_FOR;
    FOR L_i := 1 TO 2 DO GVL_IO.AO_Boiler_Setpoint[L_i] := TO_UINT(fbHeating.VO_Boiler_Setpoint[L_i] * 10.0); END_FOR;

fbSecurity(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_IsActivePLC := L_Is_Active,
    VI_Opening_Sensors := L_Opening_Sensors,
    VI_GlassBreak_Sensors := L_GlassBreak_Sensors,
    VI_Config := GVL_Vars.G_Security_Config,
    VI_Group_2F_Open := GVL_IO.DI_Security_2F_Group, // ТЗ 3.1
    VI_Group_2F_Glass := GVL_IO.DI_Security_2F_Group, // ТЗ 3.2 (используем тот же канал если не выделен)
    VO_Armed => GVL_Vars.G_Security_Armed
);

fbAccessControl(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_IsActivePLC := L_Is_Active,
    VI_Armed := GVL_Vars.G_Security_Armed,
    VI_Gate_Open_Req := GVL_Vars.G_HMI_Gate_Open_Req,
    VI_Wicket_Open_Req := GVL_Vars.G_HMI_Wicket_Open_Req,
    VI_Lock_1_Open_Req := GVL_Vars.G_HMI_Lock_1_Open_Req,
    VI_Lock_1_Close_Req := GVL_Vars.G_HMI_Lock_1_Close_Req,
    VI_Lock_2_Open_Req := GVL_Vars.G_HMI_Lock_2_Open_Req,
    VI_Lock_2_Close_Req := GVL_Vars.G_HMI_Lock_2_Close_Req,
    VI_Config := GVL_Vars.G_Security_Config
);

// Сброс команд HMI (импульсные кнопки)
IF GVL_Vars.G_HMI_Gate_Open_Req AND NOT fbAccessControl.VO_Gate_Open THEN GVL_Vars.G_HMI_Gate_Open_Req := FALSE; END_IF;
IF GVL_Vars.G_HMI_Wicket_Open_Req AND NOT fbAccessControl.VO_Wicket_Open THEN GVL_Vars.G_HMI_Wicket_Open_Req := FALSE; END_IF;
IF GVL_Vars.G_HMI_Lock_1_Open_Req AND NOT fbAccessControl.VO_Lock_1_Open THEN GVL_Vars.G_HMI_Lock_1_Open_Req := FALSE; END_IF;
IF GVL_Vars.G_HMI_Lock_1_Close_Req AND NOT fbAccessControl.VO_Lock_1_Close THEN GVL_Vars.G_HMI_Lock_1_Close_Req := FALSE; END_IF;
IF GVL_Vars.G_HMI_Lock_2_Open_Req AND NOT fbAccessControl.VO_Lock_2_Open THEN GVL_Vars.G_HMI_Lock_2_Open_Req := FALSE; END_IF;
IF GVL_Vars.G_HMI_Lock_2_Close_Req AND NOT fbAccessControl.VO_Lock_2_Close THEN GVL_Vars.G_HMI_Lock_2_Close_Req := FALSE; END_IF;

// Маппинг на физические выходы
GVL_IO.DO_Gate_Open := fbAccessControl.VO_Gate_Open;
GVL_IO.DO_Wicket_Open := fbAccessControl.VO_Wicket_Open;
GVL_IO.DO_Lock_1_Open := fbAccessControl.VO_Lock_1_Open;
GVL_IO.DO_Lock_1_Close := fbAccessControl.VO_Lock_1_Close;
GVL_IO.DO_Lock_2_Open := fbAccessControl.VO_Lock_2_Open;
GVL_IO.DO_Lock_2_Close := fbAccessControl.VO_Lock_2_Close;

fbDHW(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_IsActivePLC := L_Is_Active,
    VI_Temp := GVL_IO.AI_DHW_Temp,
    VI_Pressure := GVL_IO.AI_DHW_Pressure,
    VI_Config := GVL_Vars.G_DHW_Config,
    VI_Maintenance := GVL_Vars.G_Maintenance_Lighting[1] // Условно используем ячейку для ГВС
);
GVL_IO.DO_DHW_Heating_Pump := fbDHW.VO_Heating_Pump;
GVL_IO.DO_DHW_Circ_Pump := fbDHW.VO_Circ_Pump;

fbVentilation(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_IsActivePLC := L_Is_Active,
    VI_CO2 := L_System_State.CO2,
    VI_Humidity := L_System_State.Humidity,
    VI_Gas_Alarm := GVL_Vars.G_Gas_Alarm_Active,
    VI_Fire_Alarm := GVL_Vars.G_Fire_Alarm_Active,
    VI_Flood_Alarm := GVL_Vars.G_Flood_Alarm_Active,
    VI_Config := GVL_Vars.G_Ventilation_Config,
    VI_PV3_Boost := fbGasSmoke.VO_Vent_PV3_Boost, // ТЗ 5.1
    VI_Supply_100_Req := fbGasSmoke.VO_Supply_100_Req, // ТЗ 6.4
    VI_Exhaust_100_Req := fbGasSmoke.VO_Exhaust_100_Req, // ТЗ 6.4
    VI_Supply_80_Req := fbGasSmoke.VO_Supply_80_Req, // ТЗ 5.4
    VI_Wet_Zone_Lights := fbLightingBlinds.VO_Wet_Zone_Light_Active // ТЗ 4.0
);
// Конверсия выходов вентиляции
FOR L_i := 1 TO 3 DO GVL_IO.AO_Supply_Fans[L_i] := TO_UINT(fbVentilation.VO_Supply_Fans[L_i] * 10.0); END_FOR;
FOR L_i := 1 TO 5 DO GVL_IO.AO_Exhaust_Fans[L_i] := TO_UINT(fbVentilation.VO_Exhaust_Fans[L_i] * 10.0); END_FOR;

fbSimulation(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_Enabled := (GVL_Vars.G_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY),
    VI_Intensity := 0.3
);

fbLightingBlinds(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_IsActivePLC := L_Is_Active,
    VI_Current_Scenario := GVL_Vars.G_Current_Scenario,
    VI_Away_Level := fbSecurity.VO_Away_Level,
    VI_Simulation_Active := (GVL_Vars.G_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY),
    VI_Simulation_Lights := fbSimulation.VO_Light_States,
    VI_Physical_Switches := GVL_IO.DI_Lighting_Switches, // ТЗ 1.0
    VI_Motion_Sensors := GVL_IO.DI_Motion_Sensors, // ТЗ 2.0
    VI_Maintenance := GVL_Vars.G_Maintenance_Lighting // ТЗ 6.0
);

fbRuleEngine(VI_System_State := L_System_State);

fbGateway(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_Local_PLC_Role := SEL(L_Is_Active, E_PLC_ROLE.ROLE_STANDBY, E_PLC_ROLE.ROLE_ACTIVE),
    VI_FloorHeating_Temps := GVL_IO.AI_Floor_Temps,
    VI_Room_Temps := GVL_IO.AI_Room_Temps,
    VI_Zone_Valve_States := GVL_IO.DO_Zone_Valves,
    VI_Manifold_Pressures := L_Manifold_Pressures_Real,
    VI_Manifold_Pump_States := GVL_IO.DO_Manifold_Pumps,
    VI_Outdoor_Temp := L_System_State.Outdoor_Temp,
    VI_Security_Armed := GVL_Vars.G_Security_Armed,
    VI_Flood_Alarm_Active := GVL_Vars.G_Flood_Alarm_Active,
    VI_Gas_Alarm_Active := GVL_Vars.G_Gas_Alarm_Active,
    VI_Fire_Alarm_Active := GVL_Vars.G_Fire_Alarm_Active,
    VI_Lighting_Base_Levels := fbLightingBlinds.VO_Lighting_Levels,
    VI_Blinds_Positions := fbLightingBlinds.VO_Blinds_Positions,
    VI_Active_Scenario := GVL_Vars.G_Current_Scenario
);

FUNCTION_BLOCK FB_Alarm_Manager
VAR_INPUT
    VI_System_Time_MS : UDINT; // Системное время (мс)
    VI_IsActivePLC : BOOL; // Флаг: Данный ПЛК является ведущим

    // Входы от подсистем
    VI_Gas_Alarm : BOOL; // Сигнал тревоги: Утечка газа
    VI_Fire_Alarm : BOOL; // Сигнал тревоги: Пожар
    VI_Flood_Alarm : BOOL; // Сигнал тревоги: Протечка воды
    VI_Security_Alarm : BOOL; // Сигнал тревоги: Охранная система
    VI_First_Fault_Active : BOOL; // Активна защёлкнутая первая причина деградации
    VI_First_Fault_Type : INT; // 1=IO,2=Sensor,3=Comm,4=Subsystem
    VI_First_Fault_Source : INT; // 1=Heating,2=DHW,3=Ventilation,4=Lighting,5=Access

    // Сообщения от подсистем (для детализации)
    VI_Security_Msg : STRING(200); // Детальное сообщение от охранной системы

    // Команды с HMI
    VI_Acknowledge_All : BOOL; // Команда: Квитировать все тревоги
    VI_Mute_Siren : BOOL; // Команда: Временное отключение сирены
END_VAR
VAR_IN_OUT
    VI_Boiler_Errors : ARRAY[1..GVL_CONSTANTS.C_MAX_BOILERS] OF BOOL; // Ошибки котлов
END_VAR
VAR_IN_OUT
    VIO_Next_Alarm_ID : UDINT; // Глобальный счетчик ID тревог
END_VAR
VAR_OUTPUT
    VO_Global_Critical : BOOL; // Есть неквитированные критические аварии
    VO_Global_Warning : BOOL;  // Есть неквитированные предупреждения
    VO_Siren_Active : BOOL;    // Требуется включение сирены
    VO_Active_Count : INT;     // Количество активных тревог
    VO_Unacked_Count : INT;    // Количество неквитированных тревог
    VO_Event_Pulse : BOOL;     // Пульс события для History bridge
    VO_Event_Code : UDINT;     // 1201=ack all, 1202=alarm cleared, 1203=alarm created
    VO_Event_Value : REAL;     // Доп. значение события

    VO_Alarm_List : ARRAY[1..GVL_CONSTANTS.C_MAX_ALARMS] OF ST_Alarm_Record; // Список активных тревог для HMI
END_VAR
VAR
    fbCompatAlarm : ARRAY[1..GVL_CONSTANTS.C_MAX_ALARMS] OF FB_Alarm_Compatibility_Package_DRAFT;
    L_i, L_j, L_k : INT;
    L_Target_Slot : INT;
    L_Min_Pri : INT;
    L_Pending_Alarms : ARRAY[1..10] OF ST_Alarm_Record;
    L_Pending_Count : INT := 0;

    // Фронты и антидребезг для детекции новых тревог
    T_Debounce_Gas : FB_System_Timer;
    T_Debounce_Fire : FB_System_Timer;
    T_Debounce_Flood : FB_System_Timer;
    T_Debounce_Security : FB_System_Timer;
    R_Trig_Gas : R_TRIG;
    R_Trig_Fire : R_TRIG;
    R_Trig_Flood : R_TRIG;
    R_Trig_Security : R_TRIG;
    R_Trig_First_Fault : R_TRIG;
    R_Trig_Boiler : ARRAY[1..GVL_CONSTANTS.C_MAX_BOILERS] OF R_TRIG;
    L_First_Fault_Source_Text : STRING(32);
    L_First_Fault_Type_Text : STRING(32);
    L_Event_Pulse_Latched : BOOL;
    L_Alarm_Compat_All_OK : BOOL;
    L_Alarm_First_Warning : STRING(255);
    L_Alarm_First_Warning_Latched : BOOL;
    L_Alarm_Shadow_Mismatch : BOOL;
    L_Alarm_Shadow_First_Mismatch : INT;
    L_Alarm_V2_Switch_Enabled : BOOL;
    L_Alarm_V2_Path_Ready : BOOL;
    L_Alarm_Using_Legacy_Fallback : BOOL;
    fbAlarmV2Core : FB_Alarm_V2_Core_DRAFT;
    fbHistoryV2Core : FB_History_V2_Core_DRAFT;
    fbBlackBoxV2Core : FB_BlackBox_V2_Core_DRAFT;
    L_BlackBox_V2_Snapshot_Shadow : ST_BlackBox_Snapshot_V2;
    L_History_V2_Shadow_Diff_Found : BOOL;
    L_History_V2_Shadow_First_Diff_Slot : INT;
    L_BlackBox_V2_Shadow_Diff_Found : BOOL;
    L_History_V2_Buffer_Shadow : ARRAY[1..GVL_CONSTANTS.C_MAX_HISTORY_RECORDS] OF ST_History_Event_V2;
    L_Alarm_V2_Shadow_Compare_Enabled : BOOL;
    L_Alarm_V2_Shadow_Diff_Found : BOOL;
    L_Alarm_V2_Shadow_First_Diff_Slot : INT;
    L_Alarm_V2_Event_Pulse : BOOL;
    L_Alarm_V2_Event_Code : UDINT;
    L_Alarm_V2_Event_Value : REAL;
    L_Alarm_V2_List_Shadow : ARRAY[1..GVL_CONSTANTS.C_MAX_ALARMS] OF ST_Alarm_Record;
    L_Alarm_V2_Next_ID_Shadow : UDINT;
END_VAR

VO_Event_Pulse := FALSE;
VO_Event_Code := 0;
VO_Event_Value := 0.0;

L_Alarm_Compat_All_OK := TRUE;
L_Alarm_First_Warning := '';
L_Alarm_First_Warning_Latched := FALSE;
L_Alarm_Shadow_Mismatch := FALSE;
L_Alarm_Shadow_First_Mismatch := 0;
L_Alarm_V2_Switch_Enabled := TRUE;
L_Alarm_V2_Path_Ready := FALSE;
L_Alarm_Using_Legacy_Fallback := TRUE;
L_Alarm_V2_Shadow_Compare_Enabled := TRUE;
L_Alarm_V2_Shadow_Diff_Found := FALSE;
L_Alarm_V2_Shadow_First_Diff_Slot := 0;
L_Alarm_V2_Event_Pulse := FALSE;
L_Alarm_V2_Event_Code := 0;
L_Alarm_V2_Event_Value := 0.0;
L_Alarm_V2_Next_ID_Shadow := VIO_Next_Alarm_ID;
L_History_V2_Shadow_Diff_Found := FALSE;
L_History_V2_Shadow_First_Diff_Slot := 0;
L_BlackBox_V2_Shadow_Diff_Found := FALSE;

// 1. Детекция новых тревог (антидребезг + передний фронт)
T_Debounce_Gas(IN := VI_Gas_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Fire(IN := VI_Fire_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Flood(IN := VI_Flood_Alarm, PT := T#500ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Security(IN := VI_Security_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);

R_Trig_Gas(CLK := T_Debounce_Gas.Q);
R_Trig_Fire(CLK := T_Debounce_Fire.Q);
R_Trig_Flood(CLK := T_Debounce_Flood.Q);
R_Trig_Security(CLK := T_Debounce_Security.Q);
R_Trig_First_Fault(CLK := VI_First_Fault_Active);
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    R_Trig_Boiler[L_i](CLK := VI_Boiler_Errors[L_i]);
END_FOR;

// 2. Добавление новых тревог в список (Кольцевой буфер)
L_Pending_Count := 0;
L_Event_Pulse_Latched := FALSE;

IF R_Trig_Gas.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Gas';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Критическая концентрация газа!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Fire.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Fire';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Обнаружено задымление!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Flood.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Flood';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Обнаружена протечка воды!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Security.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Security';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := VI_Security_Msg;
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_First_Fault.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Diagnostics';
    L_Pending_Alarms[L_Pending_Count].Source_ID := TO_BYTE(VI_First_Fault_Source);

    CASE VI_First_Fault_Type OF
        1: L_First_Fault_Type_Text := 'IO';
        2: L_First_Fault_Type_Text := 'Sensor';
        3: L_First_Fault_Type_Text := 'Comm';
        4: L_First_Fault_Type_Text := 'Subsystem';
        ELSE L_First_Fault_Type_Text := 'Unknown';
    END_CASE;

    CASE VI_First_Fault_Source OF
        1: L_First_Fault_Source_Text := 'Heating';
        2: L_First_Fault_Source_Text := 'DHW';
        3: L_First_Fault_Source_Text := 'Ventilation';
        4: L_First_Fault_Source_Text := 'Lighting';
        5: L_First_Fault_Source_Text := 'Access';
        ELSE L_First_Fault_Source_Text := 'Unknown';
    END_CASE;

    L_Pending_Alarms[L_Pending_Count].Message := CONCAT('Diagnostics root cause: ', CONCAT(L_First_Fault_Source_Text, CONCAT(' / ', L_First_Fault_Type_Text)));
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF R_Trig_Boiler[L_j].Q AND L_Pending_Count < 10 THEN
        L_Pending_Count := L_Pending_Count + 1;
        L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
        L_Pending_Alarms[L_Pending_Count].Source := 'Boiler';
        L_Pending_Alarms[L_Pending_Count].Source_ID := TO_BYTE(L_j);
        L_Pending_Alarms[L_Pending_Count].Message := CONCAT('Авария котла №', INT_TO_STRING(L_j));
        L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
        L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
        L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
    END_IF;
END_FOR;

// Shadow comparison: execute Alarm V2 core on a separate shadow list.
// Legacy path remains authoritative; this is diagnostics only.
IF L_Alarm_V2_Shadow_Compare_Enabled THEN
    fbAlarmV2Core(
        VI_System_Time_MS := VI_System_Time_MS,
        VI_Pending_Alarms := L_Pending_Alarms,
        VIO_Alarm_List := L_Alarm_V2_List_Shadow,
        VIO_Next_Alarm_ID := L_Alarm_V2_Next_ID_Shadow,
        VO_Event_Pulse => L_Alarm_V2_Event_Pulse,
        VO_Event_Code => L_Alarm_V2_Event_Code,
        VO_Event_Value => L_Alarm_V2_Event_Value
    );
END_IF;

// Staging integration: Alarm V2 core is called behind the phase-4 switch scaffold.
// Current state: switch remains disabled, so legacy path stays authoritative.
IF L_Alarm_V2_Switch_Enabled AND L_Alarm_V2_Path_Ready THEN
    fbAlarmV2Core(
        VI_System_Time_MS := VI_System_Time_MS,
        VI_Pending_Alarms := L_Pending_Alarms,
        VIO_Alarm_List := VO_Alarm_List,
        VIO_Next_Alarm_ID := VIO_Next_Alarm_ID
    );
END_IF;

// Обработка очереди новых тревог с учетом приоритетов
FOR L_i := 1 TO L_Pending_Count DO
    fbCompatAlarm[L_i](VI_Alarm_Legacy := L_Pending_Alarms[L_i]);

    IF NOT fbCompatAlarm[L_i].VO_OK THEN
        L_Alarm_Compat_All_OK := FALSE;
    END_IF;

    IF (NOT L_Alarm_First_Warning_Latched) AND (NOT fbCompatAlarm[L_i].VO_OK) THEN
        L_Alarm_First_Warning := 'Translation issue';
        L_Alarm_First_Warning_Latched := TRUE;
    END_IF;

    IF fbCompatAlarm[L_i].VO_Alarm_Legacy_Roundtrip.ID <> L_Pending_Alarms[L_i].ID THEN
        L_Alarm_Shadow_Mismatch := TRUE;
        IF L_Alarm_Shadow_First_Mismatch = 0 THEN
            L_Alarm_Shadow_First_Mismatch := L_i;
        END_IF;
    END_IF;
    // Phase 4 scaffold: optional Alarm V2 switch point.
    // Current state: always remain on legacy behavior.
    // Future state: when Alarm V2 path is implemented and validated,
    // this block becomes the controlled branch point.
    IF L_Alarm_V2_Switch_Enabled AND L_Alarm_V2_Path_Ready THEN
        L_Alarm_Using_Legacy_Fallback := FALSE;
        // Guarded V2 pipeline is allowed by shadow validation.
        // Current runtime logic still keeps legacy action flow authoritative until next package.
    ELSE
        L_Alarm_Using_Legacy_Fallback := TRUE;
    END_IF;

    L_Target_Slot := 0;

    // 1. Ищем пустой слот
    FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF VO_Alarm_List[L_k].ID = 0 THEN
            L_Target_Slot := L_k;
            EXIT;
        END_IF;
    END_FOR;

    // 2. Ищем квитированную тревогу с наименьшим приоритетом
    IF L_Target_Slot = 0 THEN
        L_Min_Pri := 999;
        FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
            IF VO_Alarm_List[L_k].Is_Acknowledged AND TO_INT(VO_Alarm_List[L_k].Severity) < L_Min_Pri THEN
                L_Min_Pri := TO_INT(VO_Alarm_List[L_k].Severity);
                L_Target_Slot := L_k;
            END_IF;
        END_FOR;
    END_IF;

    // 3. Ищем неквитированную тревогу с наименьшим приоритетом (если он ниже добавляемой)
    IF L_Target_Slot = 0 THEN
        L_Min_Pri := 999;
        FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
            IF TO_INT(VO_Alarm_List[L_k].Severity) < L_Min_Pri AND TO_INT(VO_Alarm_List[L_k].Severity) < TO_INT(L_Pending_Alarms[L_i].Severity) THEN
                L_Min_Pri := TO_INT(VO_Alarm_List[L_k].Severity);
                L_Target_Slot := L_k;
            END_IF;
        END_FOR;
    END_IF;

    IF L_Target_Slot = 0 THEN 
        // Буфер полон критических неквитированных тревог. Не затираем!
        CONTINUE; 
    END_IF;

    VO_Alarm_List[L_Target_Slot] := L_Pending_Alarms[L_i];
    VO_Alarm_List[L_Target_Slot].ID := VIO_Next_Alarm_ID;
    VIO_Next_Alarm_ID := VIO_Next_Alarm_ID + 1;
    IF VIO_Next_Alarm_ID = 0 THEN VIO_Next_Alarm_ID := 1; END_IF;
    IF NOT L_Event_Pulse_Latched THEN
        VO_Event_Pulse := TRUE;
        VO_Event_Code := 1203;
        VO_Event_Value := TO_REAL(VO_Alarm_List[L_Target_Slot].Severity);
        L_Event_Pulse_Latched := TRUE;
    END_IF;
END_FOR;

// Shadow comparison results: compare legacy output and V2 shadow output.
IF L_Alarm_V2_Shadow_Compare_Enabled THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF (VO_Alarm_List[L_i].ID <> L_Alarm_V2_List_Shadow[L_i].ID)
           OR (VO_Alarm_List[L_i].Is_Active <> L_Alarm_V2_List_Shadow[L_i].Is_Active)
           OR (VO_Alarm_List[L_i].Is_Acknowledged <> L_Alarm_V2_List_Shadow[L_i].Is_Acknowledged)
           OR (VO_Alarm_List[L_i].Severity <> L_Alarm_V2_List_Shadow[L_i].Severity) THEN
            L_Alarm_V2_Shadow_Diff_Found := TRUE;
            IF L_Alarm_V2_Shadow_First_Diff_Slot = 0 THEN
                L_Alarm_V2_Shadow_First_Diff_Slot := L_i;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

// 3. Обновление статуса существующих тревог (ушли ли они?)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 THEN
        IF VO_Alarm_List[L_i].Source = 'Gas' THEN VO_Alarm_List[L_i].Is_Active := VI_Gas_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Fire' THEN VO_Alarm_List[L_i].Is_Active := VI_Fire_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Flood' THEN VO_Alarm_List[L_i].Is_Active := VI_Flood_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Security' THEN VO_Alarm_List[L_i].Is_Active := VI_Security_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Diagnostics' THEN VO_Alarm_List[L_i].Is_Active := VI_First_Fault_Active;
        ELSIF VO_Alarm_List[L_i].Source = 'Boiler' THEN 
            IF TO_INT(VO_Alarm_List[L_i].Source_ID) >= 1 AND TO_INT(VO_Alarm_List[L_i].Source_ID) <= GVL_CONSTANTS.C_MAX_BOILERS THEN
                VO_Alarm_List[L_i].Is_Active := VI_Boiler_Errors[TO_INT(VO_Alarm_List[L_i].Source_ID)];
            END_IF;
        END_IF;
    END_IF;
END_FOR;

// 4. Квитирование тревог
IF VI_Acknowledge_All THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF VO_Alarm_List[L_i].ID <> 0 THEN
            VO_Alarm_List[L_i].Is_Acknowledged := TRUE;
        END_IF;
    END_FOR;

    IF NOT L_Event_Pulse_Latched THEN
        VO_Event_Pulse := TRUE;
        VO_Event_Code := 1201;
        VO_Event_Value := TO_REAL(VO_Unacked_Count);
        L_Event_Pulse_Latched := TRUE;
    END_IF;
END_IF;

// 4.5 Автоквитирование некритичных тревог, если они больше не активны
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 AND NOT VO_Alarm_List[L_i].Is_Active AND NOT VO_Alarm_List[L_i].Is_Acknowledged THEN
        IF VO_Alarm_List[L_i].Severity <> E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL THEN
            VO_Alarm_List[L_i].Is_Acknowledged := TRUE;
        END_IF;
    END_IF;
END_FOR;

// 5. Очистка списка (удаление неактивных И квитированных тревог)
// В кольцевом буфере мы просто помечаем слот как пустой (ID = 0), без сдвига массива
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 AND NOT VO_Alarm_List[L_i].Is_Active AND VO_Alarm_List[L_i].Is_Acknowledged THEN
        // Удаляем тревогу
        VO_Alarm_List[L_i].ID := 0;
        IF NOT L_Event_Pulse_Latched THEN
            VO_Event_Pulse := TRUE;
            VO_Event_Code := 1202;
            VO_Event_Value := 0.0;
            L_Event_Pulse_Latched := TRUE;
        END_IF;
    END_IF;
END_FOR;

// Shadow bridge: Alarm -> History V2 (diagnostic only)
fbHistoryV2Core(
    VI_Event_Pulse := VO_Event_Pulse,
    VI_Event_Code := VO_Event_Code,
    VI_Event_Value := VO_Event_Value,
    VI_System_Time_MS := VI_System_Time_MS,
    VIO_History_Buffer := L_History_V2_Buffer_Shadow
);

// Shadow bridge: System -> BlackBox V2 (diagnostic only)
fbBlackBoxV2Core(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_System_Mode := 0,
    VI_Critical_Alarm_Active := VO_Global_Critical,
    VI_Warning_Active := VO_Global_Warning,
    VI_First_Fault_Type := TO_BYTE(VI_First_Fault_Type),
    VI_First_Fault_Source := TO_BYTE(VI_First_Fault_Source),
    VI_Gas_Alarm := VI_Gas_Alarm,
    VI_Fire_Alarm := VI_Fire_Alarm,
    VI_Flood_Alarm := VI_Flood_Alarm,
    VO_Snapshot => L_BlackBox_V2_Snapshot_Shadow
);

// Shadow validation: History V2 / BlackBox V2
IF VO_Event_Pulse THEN
    IF (L_History_V2_Buffer_Shadow[1].Event_Code <> VO_Event_Code)
       OR (ABS(L_History_V2_Buffer_Shadow[1].Event_Value - VO_Event_Value) > 0.0001) THEN
        L_History_V2_Shadow_Diff_Found := TRUE;
        IF L_History_V2_Shadow_First_Diff_Slot = 0 THEN
            L_History_V2_Shadow_First_Diff_Slot := 1;
        END_IF;
    END_IF;
END_IF;

IF (L_BlackBox_V2_Snapshot_Shadow.Gas_Alarm <> VI_Gas_Alarm)
   OR (L_BlackBox_V2_Snapshot_Shadow.Fire_Alarm <> VI_Fire_Alarm)
   OR (L_BlackBox_V2_Snapshot_Shadow.Flood_Alarm <> VI_Flood_Alarm)
   OR (L_BlackBox_V2_Snapshot_Shadow.First_Fault_Type <> TO_BYTE(VI_First_Fault_Type))
   OR (L_BlackBox_V2_Snapshot_Shadow.First_Fault_Source <> TO_BYTE(VI_First_Fault_Source)) THEN
    L_BlackBox_V2_Shadow_Diff_Found := TRUE;
END_IF;

// Guarded V2 pipeline enable:
// V2 path is allowed only when no shadow diff is present in Alarm/History/BlackBox.
IF L_Alarm_V2_Switch_Enabled THEN
    IF (NOT L_Alarm_V2_Shadow_Diff_Found)
       AND (NOT L_History_V2_Shadow_Diff_Found)
       AND (NOT L_BlackBox_V2_Shadow_Diff_Found) THEN
        L_Alarm_V2_Path_Ready := TRUE;
        L_Alarm_Using_Legacy_Fallback := FALSE;
    ELSE
        L_Alarm_V2_Path_Ready := FALSE;
        L_Alarm_Using_Legacy_Fallback := TRUE;
    END_IF;
ELSE
    L_Alarm_V2_Path_Ready := FALSE;
    L_Alarm_Using_Legacy_Fallback := TRUE;
END_IF;

// 6. Подсчет статистики и формирование глобальных флагов
VO_Global_Critical := FALSE;
VO_Global_Warning := FALSE;
VO_Siren_Active := FALSE;
VO_Active_Count := 0;
VO_Unacked_Count := 0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 THEN
        IF VO_Alarm_List[L_i].Is_Active THEN
            VO_Active_Count := VO_Active_Count + 1;
        END_IF;

        IF NOT VO_Alarm_List[L_i].Is_Acknowledged THEN
            VO_Unacked_Count := VO_Unacked_Count + 1;

            IF VO_Alarm_List[L_i].Severity = E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL THEN
                VO_Global_Critical := TRUE;
                // Сирена работает только для неквитированных критических тревог, если не включен Mute
                IF NOT VI_Mute_Siren THEN
                    VO_Siren_Active := TRUE;
                END_IF;
            ELSIF VO_Alarm_List[L_i].Severity = E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH THEN
                VO_Global_Warning := TRUE;
            END_IF;
        END_IF;
    END_IF;
END_FOR;
// >>> BULK_SYNC_ANCHOR: FB_Alarm_Manager <<<

FUNCTION_BLOCK FB_Analog_Validator
VAR_INPUT
    VI_Value : REAL;
    VI_Min_Valid : REAL;
    VI_Max_Valid : REAL;
    VI_Fallback_Mode : INT := 0; // 0: Hold last good, 1: Default value
    VI_Default_Value : REAL := 0.0;
END_VAR
VAR_OUTPUT
    VO_Value : REAL;
    VO_Error : BOOL;
END_VAR
VAR
    L_Last_Good_Value : REAL;
    L_First_Valid : BOOL := FALSE;
END_VAR

IF VI_Value >= VI_Min_Valid AND VI_Value <= VI_Max_Valid THEN
    VO_Error := FALSE;
    VO_Value := VI_Value;
    L_Last_Good_Value := VI_Value;
    L_First_Valid := TRUE;
ELSE
    VO_Error := TRUE;
    IF VI_Fallback_Mode = 1 OR NOT L_First_Valid THEN
        VO_Value := VI_Default_Value;
    ELSE
        VO_Value := L_Last_Good_Value;
    END_IF;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Analog_Validator <<<

FUNCTION_BLOCK FB_Fault_Logger
VAR_INPUT
    VI_Severity  : E_System_Severity;
    VI_RootCause : E_System_Root_Cause;
    VI_Time_MS   : UDINT;
END_VAR

VAR_OUTPUT
    VO_Last_Event_Text : STRING(200);
    VO_Event_Count     : UINT;
    VO_Last_Index      : UINT;

    VO_Event_Time_MS   : ARRAY[1..16] OF UDINT;
    VO_Event_Severity  : ARRAY[1..16] OF E_System_Severity;
    VO_Event_RootCause : ARRAY[1..16] OF E_System_Root_Cause;
    VO_Event_Text      : ARRAY[1..16] OF STRING(200);
END_VAR

VAR
    L_Last_Severity  : E_System_Severity;
    L_Last_RootCause : E_System_Root_Cause;
    L_Write_Index    : UINT := 0;
    L_Event_Text     : STRING(200);
END_VAR

L_Event_Text := '';

IF (VI_Severity <> L_Last_Severity) OR (VI_RootCause <> L_Last_RootCause) THEN
    CASE VI_RootCause OF
        E_System_Root_Cause.ROOT_FIRE:
            L_Event_Text := 'EVENT: FIRE DETECTED';
        E_System_Root_Cause.ROOT_GAS_LEAK:
            L_Event_Text := 'EVENT: GAS LEAK';
        E_System_Root_Cause.ROOT_CO_CRITICAL:
            L_Event_Text := 'EVENT: CO CRITICAL';
        E_System_Root_Cause.ROOT_CO_WARNING:
            L_Event_Text := 'EVENT: CO WARNING';
        E_System_Root_Cause.ROOT_WATER_LEAK:
            L_Event_Text := 'EVENT: WATER LEAK';
        E_System_Root_Cause.ROOT_SENSOR_FAULT:
            L_Event_Text := 'EVENT: SENSOR FAULT';
        E_System_Root_Cause.ROOT_IO_OFFLINE:
            L_Event_Text := 'EVENT: IO OFFLINE';
        E_System_Root_Cause.ROOT_COMM_FAULT:
            L_Event_Text := 'EVENT: COMM FAULT';
        E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
            L_Event_Text := 'EVENT: WATCHDOG FAULT';
        E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT:
            L_Event_Text := 'EVENT: SUBSYSTEM FAULT';
        ELSE
            L_Event_Text := 'EVENT: SYSTEM STATE CHANGE';
    END_CASE;

    L_Write_Index := L_Write_Index + 1;
    IF L_Write_Index > 16 THEN
        L_Write_Index := 1;
    END_IF;

    VO_Event_Time_MS[L_Write_Index] := VI_Time_MS;
    VO_Event_Severity[L_Write_Index] := VI_Severity;
    VO_Event_RootCause[L_Write_Index] := VI_RootCause;
    VO_Event_Text[L_Write_Index] := L_Event_Text;

    VO_Last_Index := L_Write_Index;
    VO_Last_Event_Text := L_Event_Text;

    IF VO_Event_Count < 16 THEN
        VO_Event_Count := VO_Event_Count + 1;
    END_IF;
END_IF;

L_Last_Severity := VI_Severity;
L_Last_RootCause := VI_RootCause;
// >>> BULK_SYNC_ANCHOR: FB_Fault_Logger <<<

FUNCTION_BLOCK FB_HMI_Interface
VAR_INPUT
    VI_Severity   : E_System_Severity;
    VI_RootCause  : E_System_Root_Cause;
    VI_Status_Msg : STRING(200);
END_VAR

VAR_OUTPUT
    VO_HMI_Status_Text : STRING(200);
    VO_HMI_State_Code  : INT;
END_VAR

VO_HMI_Status_Text := VI_Status_Msg;

CASE VI_Severity OF
    E_System_Severity.SEV_NORMAL:
        VO_HMI_State_Code := 0;
    E_System_Severity.SEV_WARNING:
        VO_HMI_State_Code := 1;
    E_System_Severity.SEV_DEGRADED:
        VO_HMI_State_Code := 2;
    E_System_Severity.SEV_CRITICAL:
        VO_HMI_State_Code := 3;
END_CASE;
// >>> BULK_SYNC_ANCHOR: FB_HMI_Interface <<<

FUNCTION_BLOCK FB_IO_Module_Watchdog
VAR_INPUT
    VI_System_Time_MS : UDINT;
    VI_Module_ID : BYTE;
    VI_Heartbeat_Signal : BOOL; // Сигнал от модуля (например, мигающий бит)
    VI_Timeout_MS : UDINT := 2000; // Таймаут 2 секунды по умолчанию
END_VAR
VAR_OUTPUT
    VO_Module_Online : BOOL;
    VO_Error_Active : BOOL;
END_VAR
VAR
    L_Last_Heartbeat_State : BOOL;
    L_Last_Heartbeat_Time : UDINT;
    L_Elapsed_Time : UDINT;
END_VAR

// Отслеживание изменения сигнала
IF VI_Heartbeat_Signal <> L_Last_Heartbeat_State THEN
    L_Last_Heartbeat_Time := VI_System_Time_MS;
    L_Last_Heartbeat_State := VI_Heartbeat_Signal;
END_IF;

// Проверка таймаута
L_Elapsed_Time := F_TimeDiff(VI_System_Time_MS, L_Last_Heartbeat_Time);

IF L_Elapsed_Time > VI_Timeout_MS THEN
    VO_Module_Online := FALSE;
    VO_Error_Active := TRUE;
ELSE
    VO_Module_Online := TRUE;
    VO_Error_Active := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_IO_Module_Watchdog <<<

FUNCTION_BLOCK FB_Redundancy_Manager
VAR_INPUT
    VI_System_Time_MS : UDINT; // Системное время (мс)
    VI_Local_PLC_ID : BYTE; // 1 = ПЛК А, 2 = ПЛК B
    VI_Remote_Pulse : BOOL; // Сигнал от партнера
    VI_Remote_Is_Active : BOOL; // Статус партнера
    VI_Gateway_Ping_OK : BOOL; // Пинг до шлюза
    VI_Remote_State : ST_System_State_Snapshot; // Состояние партнера
    VI_Local_State : ST_System_State_Snapshot; // Локальное состояние
END_VAR
VAR_OUTPUT
    VO_Local_Role : E_PLC_ROLE; // Локальная роль ПЛК (Active/Standby)
    VO_Local_Pulse : BOOL; // Локальный сигнал пульса для партнера
    VO_Sync_Data_Req : BOOL; // Запрос на синхронизацию данных
    VO_Status_Msg : STRING(200); // Строковое сообщение о статусе
    VO_Synced_State : ST_System_State_Snapshot; // Синхронизированное состояние
    VO_State_Updated : BOOL; // Флаг: Состояние было обновлено
END_VAR
VAR
    L_Heartbeat : FB_PLC_Heartbeat;
    L_Pulse_Timer : FB_System_Timer;
    L_Pulse_State : BOOL;
    L_Prev_Role : E_PLC_ROLE;
    L_State_Replicator : FB_State_Replication;
END_VAR

// 1. Генерация собственного пульса (меандр 100 мс)
L_Pulse_Timer(IN := NOT L_Pulse_Timer.Q, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
IF L_Pulse_Timer.Q THEN
    L_Pulse_State := NOT L_Pulse_State;
END_IF;
VO_Local_Pulse := L_Pulse_State;

// 2. Определение роли через Heartbeat
L_Heartbeat(
    VI_Local_ID := VI_Local_PLC_ID,
    VI_System_Time := VI_System_Time_MS,
    VI_Remote_Pulse := VI_Remote_Pulse,
    VI_Remote_Is_Active := VI_Remote_Is_Active,
    VI_Gateway_Ping_OK := VI_Gateway_Ping_OK
);

IF L_Heartbeat.VO_Is_Active THEN
    VO_Local_Role := E_PLC_ROLE.ROLE_ACTIVE;
    VO_Status_Msg := 'ПЛК АКТИВЕН (ВЕДУЩИЙ)';
ELSE
    VO_Local_Role := E_PLC_ROLE.ROLE_STANDBY;
    VO_Status_Msg := 'ПЛК В РЕЗЕРВЕ (ВЕДОМЫЙ)';
END_IF;

// 3. Запрос на синхронизацию при переходе в ACTIVE
IF VO_Local_Role = E_PLC_ROLE.ROLE_ACTIVE AND L_Prev_Role = E_PLC_ROLE.ROLE_STANDBY THEN
    VO_Sync_Data_Req := TRUE;
ELSE
    VO_Sync_Data_Req := FALSE;
END_IF;

L_State_Replicator(
    VI_Local_Role := VO_Local_Role,
    VI_Sync_Req := VO_Sync_Data_Req,
    VI_Local_State := VI_Local_State,
    VI_Remote_State := VI_Remote_State,
    VI_System_Time_MS := VI_System_Time_MS
);
VO_Synced_State := L_State_Replicator.VO_Synced_State;
VO_State_Updated := L_State_Replicator.VO_State_Updated;

L_Prev_Role := VO_Local_Role;
// >>> BULK_SYNC_ANCHOR: FB_Redundancy_Manager <<<

FUNCTION_BLOCK FB_Rule_Engine
VAR_INPUT
    VI_System_Time_MS : UDINT; // Системное время (мс)
    VI_IsActivePLC : BOOL; // Флаг: Данный ПЛК является ведущим
    VI_Security_Armed : BOOL; // Статус: Система под охраной
    VI_Current_Time : TOD; // Текущее время суток
    VI_Day_Of_Week : INT; // Текущий день недели (1..7, 1 = Понедельник)
END_VAR
VAR_IN_OUT
    VI_Rules : ARRAY[1..GVL_CONSTANTS.C_MAX_RULES] OF ST_User_Rule; // Массив пользовательских правил
    VI_Indoor_Temps : ARRAY[1..GVL_CONSTANTS.C_MAX_CLIMATE_ZONES] OF REAL; // Температуры в помещениях
    VI_Floor_Temps : ARRAY[1..GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS] OF REAL; // Температуры пола
    VI_Humidities : ARRAY[1..GVL_CONSTANTS.C_MAX_CLIMATE_ZONES] OF REAL; // Влажность в помещениях
    VI_CO2_Levels : ARRAY[1..GVL_CONSTANTS.C_MAX_CLIMATE_ZONES] OF REAL; // Уровни CO2
    VI_Motion_Sensors : ARRAY[1..GVL_CONSTANTS.C_MAX_CLIMATE_ZONES] OF BOOL; // Датчики движения
    VI_Door_Sensors : ARRAY[1..GVL_CONSTANTS.C_MAX_DOOR_SENSORS] OF BOOL; // Датчики открытия дверей
    VI_Window_Sensors : ARRAY[1..GVL_CONSTANTS.C_MAX_CLIMATE_ZONES] OF BOOL; // Датчики открытия окон
    VI_Water_Sensors : ARRAY[1..GVL_CONSTANTS.C_MAX_FLOOD_SENSORS] OF BOOL; // Датчики протечки воды
    VI_Smoke_Sensors : ARRAY[1..GVL_CONSTANTS.C_MAX_SMOKE_SENSORS] OF BOOL; // Датчики дыма
    VI_Methane_Sensors : ARRAY[1..GVL_CONSTANTS.C_MAX_METHANE_SENSORS] OF REAL; // Датчики метана
    VI_CO_Sensors : ARRAY[1..GVL_CONSTANTS.C_MAX_CO_SENSORS] OF REAL; // Датчики угарного газа
END_VAR
VAR_OUTPUT
    VO_Actions : ARRAY[1..GVL_CONSTANTS.C_MAX_RULES] OF ST_Rule_Action; // Сформированные действия по правилам
END_VAR
VAR
    L_i : INT;
    fbCompat : ARRAY[1..GVL_CONSTANTS.C_MAX_RULES] OF FB_Rule_Compatibility_Package_DRAFT;
    L_Compat_All_OK : BOOL;
    L_Compat_First_Warning : STRING(255);
    L_Compat_First_Warning_Latched : BOOL;
    L_Shadow_V2_Enabled : BOOL;
    L_Shadow_V2_Roundtrip_Mismatch : BOOL;
    L_Shadow_V2_First_Mismatch_Rule : INT;
    L_V2_Switch_Enabled : BOOL;
    L_V2_Path_Ready : BOOL;
    L_V2_Using_Legacy_Fallback : BOOL;
    L_Condition_Met : BOOL;
    L_Current_Value : REAL;
    L_Triggers : ARRAY[1..GVL_CONSTANTS.C_MAX_RULES] OF R_TRIG;
    L_Trigger_Count : ARRAY[1..GVL_CONSTANTS.C_MAX_RULES] OF UINT;
    L_Last_Reset_Time : UDINT;
    L_Elapsed_Time : UDINT;
END_VAR

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

L_Compat_All_OK := TRUE;
L_Compat_First_Warning := '';
L_Compat_First_Warning_Latched := FALSE;
L_Shadow_V2_Enabled := TRUE;
L_Shadow_V2_Roundtrip_Mismatch := FALSE;
L_Shadow_V2_First_Mismatch_Rule := 0;
L_V2_Switch_Enabled := FALSE;
L_V2_Path_Ready := FALSE;
L_V2_Using_Legacy_Fallback := TRUE;

// Сброс счетчиков срабатываний каждую минуту (защита от циклических зависимостей/дребезга)
L_Elapsed_Time := F_TimeDiff(VI_System_Time_MS, L_Last_Reset_Time);

IF L_Elapsed_Time >= GVL_CONSTANTS.C_MS_IN_MINUTE THEN
    L_Last_Reset_Time := VI_System_Time_MS;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        L_Trigger_Count[L_i] := 0;
    END_FOR;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
    fbCompat[L_i](VI_Rule_Legacy := VI_Rules[L_i]);

    IF NOT fbCompat[L_i].VO_Forward_OK OR NOT fbCompat[L_i].VO_Reverse_OK THEN
        L_Compat_All_OK := FALSE;
    END_IF;

    IF (NOT L_Compat_First_Warning_Latched) AND (fbCompat[L_i].VO_Warning_Text <> '') THEN
        L_Compat_First_Warning := fbCompat[L_i].VO_Warning_Text;
        L_Compat_First_Warning_Latched := TRUE;
    END_IF;

    IF L_Shadow_V2_Enabled THEN
        IF (fbCompat[L_i].VO_Rule_Legacy_Roundtrip.Action_Type <> VI_Rules[L_i].Action_Type)
           OR (fbCompat[L_i].VO_Rule_Legacy_Roundtrip.Action_Target_ID <> VI_Rules[L_i].Action_Target_ID)
           OR (ABS(fbCompat[L_i].VO_Rule_Legacy_Roundtrip.Action_Value - VI_Rules[L_i].Action_Value) > 0.0001)
           OR (fbCompat[L_i].VO_Rule_Legacy_Roundtrip.Condition_Type <> VI_Rules[L_i].Condition_Type)
           OR (fbCompat[L_i].VO_Rule_Legacy_Roundtrip.Condition_Target_ID <> VI_Rules[L_i].Condition_Target_ID)
           OR (fbCompat[L_i].VO_Rule_Legacy_Roundtrip.Condition_Op <> VI_Rules[L_i].Condition_Op)
           OR (ABS(fbCompat[L_i].VO_Rule_Legacy_Roundtrip.Condition_Value - VI_Rules[L_i].Condition_Value) > 0.0001)
           OR (ABS(fbCompat[L_i].VO_Rule_Legacy_Roundtrip.Condition_Value_Max - VI_Rules[L_i].Condition_Value_Max) > 0.0001) THEN
            L_Shadow_V2_Roundtrip_Mismatch := TRUE;
            IF L_Shadow_V2_First_Mismatch_Rule = 0 THEN
                L_Shadow_V2_First_Mismatch_Rule := L_i;
            END_IF;
        END_IF;
    END_IF;

    // Phase 4 scaffold: optional V2 switch point.
    // Current state: always remain on legacy behavior.
    // Future state: when V2 path is implemented and validated,
    // this block becomes the controlled branch point.
    IF L_V2_Switch_Enabled AND L_V2_Path_Ready THEN
        L_V2_Using_Legacy_Fallback := FALSE;
        // V2 action-generation path placeholder.
        // No runtime behavior change yet.
    ELSE
        L_V2_Using_Legacy_Fallback := TRUE;
    END_IF;

    VO_Actions[L_i].Active := FALSE;
    IF VI_Rules[L_i].Enabled THEN
        L_Condition_Met := FALSE;
        L_Current_Value := 0.0;

        // Определение значения для проверки
        IF VI_Rules[L_i].Condition_Target_ID > 0 THEN
            CASE VI_Rules[L_i].Condition_Type OF
                E_Rule_Condition_Type.COND_AIR_TEMP: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_CLIMATE_ZONES THEN L_Current_Value := VI_Indoor_Temps[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_FLOOR_TEMP: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS THEN L_Current_Value := VI_Floor_Temps[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_HUMIDITY: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_CLIMATE_ZONES THEN L_Current_Value := VI_Humidities[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_CO2: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_CLIMATE_ZONES THEN L_Current_Value := VI_CO2_Levels[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_MOTION: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_CLIMATE_ZONES THEN L_Current_Value := SEL(VI_Motion_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_DOOR_WINDOW: 
                    IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_DOOR_SENSORS THEN
                        L_Current_Value := SEL(VI_Door_Sensors[VI_Rules[L_i].Condition_Target_ID] OR VI_Window_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    ELSIF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_CLIMATE_ZONES THEN
                        L_Current_Value := SEL(VI_Window_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    END_IF;
                E_Rule_Condition_Type.COND_FLOOD: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_FLOOD_SENSORS THEN L_Current_Value := SEL(VI_Water_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_SMOKE: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_SMOKE_SENSORS THEN L_Current_Value := SEL(VI_Smoke_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_METHANE: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_METHANE_SENSORS THEN L_Current_Value := VI_Methane_Sensors[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_CO: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_CO_SENSORS THEN L_Current_Value := VI_CO_Sensors[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_TIME_OF_DAY: L_Current_Value := TO_REAL(TOD_TO_UDINT(VI_Current_Time) / GVL_CONSTANTS.C_MS_IN_MINUTE); // Время в минутах
                E_Rule_Condition_Type.COND_DAY_OF_WEEK: L_Current_Value := TO_REAL(VI_Day_Of_Week);
            END_CASE;
        ELSE
            IF VI_Rules[L_i].Condition_Type = E_Rule_Condition_Type.COND_TIME_OF_DAY THEN
                L_Current_Value := TO_REAL(TOD_TO_UDINT(VI_Current_Time) / GVL_CONSTANTS.C_MS_IN_MINUTE); // Время в минутах
            ELSIF VI_Rules[L_i].Condition_Type = E_Rule_Condition_Type.COND_DAY_OF_WEEK THEN
                L_Current_Value := TO_REAL(VI_Day_Of_Week);
            END_IF;
        END_IF;

        // Проверка условия
        CASE VI_Rules[L_i].Condition_Op OF
            E_Rule_Comparison.COMP_GT: L_Condition_Met := (L_Current_Value > VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_LT: L_Condition_Met := (L_Current_Value < VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_EQ: L_Condition_Met := (ABS(L_Current_Value - VI_Rules[L_i].Condition_Value) < 0.1);
            E_Rule_Comparison.COMP_GE: L_Condition_Met := (L_Current_Value >= VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_LE: L_Condition_Met := (L_Current_Value <= VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_IN_RANGE: L_Condition_Met := (L_Current_Value >= VI_Rules[L_i].Condition_Value) AND (L_Current_Value <= VI_Rules[L_i].Condition_Value_Max);
            E_Rule_Comparison.COMP_TRUE: L_Condition_Met := (L_Current_Value > 0.5);
            E_Rule_Comparison.COMP_FALSE: L_Condition_Met := (L_Current_Value < 0.5);
        END_CASE;

        // Формирование действия
        L_Triggers[L_i](CLK := L_Condition_Met);

        IF L_Triggers[L_i].Q THEN
            L_Trigger_Count[L_i] := L_Trigger_Count[L_i] + 1;
            IF L_Trigger_Count[L_i] > 10 THEN
                // ТЗ 13.5: Блокировка правила при слишком частом срабатывании (циклическая зависимость)
                VO_Actions[L_i].Active := FALSE;
                VO_Actions[L_i].Triggered := FALSE;
                CONTINUE; // Пропускаем выполнение
            END_IF;
        END_IF;

        IF L_Condition_Met AND (L_Trigger_Count[L_i] <= 10) THEN
            VO_Actions[L_i].Active := TRUE;
            VO_Actions[L_i].Triggered := L_Triggers[L_i].Q;
            VO_Actions[L_i].Action_Type := VI_Rules[L_i].Action_Type;
            VO_Actions[L_i].Target_ID := VI_Rules[L_i].Action_Target_ID;
            VO_Actions[L_i].Value := VI_Rules[L_i].Action_Value;
        END_IF;
    END_IF;
END_FOR;
// >>> BULK_SYNC_ANCHOR: FB_Rule_Engine <<<

FUNCTION_BLOCK FB_Safety_Manager
VAR_INPUT
    VI_Gas_Alarm : BOOL;
    VI_Leak_Alarm : BOOL;
    VI_Smoke_Alarm : BOOL;
    VI_Reset : BOOL; // Ручной сброс защёлкнутых safety-аварий оператором
END_VAR
VAR_OUTPUT
    VO_Gas_Latched : BOOL;
    VO_Leak_Latched : BOOL;
    VO_Smoke_Latched : BOOL;
    VO_Emergency_Stop : BOOL;
END_VAR
VAR
    L_Any_Active : BOOL;
END_VAR

// Защёлкиваем аварии независимо друг от друга
IF VI_Gas_Alarm THEN
    VO_Gas_Latched := TRUE;
END_IF;

IF VI_Leak_Alarm THEN
    VO_Leak_Latched := TRUE;
END_IF;

IF VI_Smoke_Alarm THEN
    VO_Smoke_Latched := TRUE;
END_IF;

L_Any_Active := VI_Gas_Alarm OR VI_Leak_Alarm OR VI_Smoke_Alarm;

// Ручной сброс допустим только когда все входные аварийные сигналы уже исчезли
IF VI_Reset AND NOT L_Any_Active THEN
    VO_Gas_Latched := FALSE;
    VO_Leak_Latched := FALSE;
    VO_Smoke_Latched := FALSE;
END_IF;

// Агрегированный аварийный стоп = любая защёлкнутая safety-авария
VO_Emergency_Stop := VO_Gas_Latched OR VO_Leak_Latched OR VO_Smoke_Latched;
END_FUNCTION_BLOCK
// >>> BULK_SYNC_ANCHOR: FB_Safety_Manager <<<

FUNCTION_BLOCK FB_Socket_Manager
// Менеджер управления розетками.
// Обеспечивает работу по сценариям, правилам и аварийное отключение (без локальных выключателей розеток).
VAR_INPUT
    VI_System_Time_MS : UDINT; // Системное время в миллисекундах
    VI_IsActivePLC : BOOL; // Флаг активности ПЛК (TRUE = ведущий)
    VI_Scenario : E_SCENARIO_TYPE; // Текущий глобальный сценарий
    VI_Fire_Alarm : BOOL; // Флаг пожарной тревоги
    VI_Flood_Alarm : BOOL; // Флаг тревоги протечки
    VI_Security_Armed : BOOL; // Состояние охраны (TRUE = включена)
END_VAR
VAR_IN_OUT
    VI_Manual_Override : ARRAY[1..GVL_CONSTANTS.C_MAX_SOCKETS] OF BOOL; // Ручное переопределение состояния (HMI)
    VI_Physical_Switches : ARRAY[1..GVL_CONSTANTS.C_MAX_SOCKETS] OF BOOL; // Legacy-вход: не используется в текущей концепции
    VI_Rule_Actions : ARRAY[1..GVL_CONSTANTS.C_MAX_RULES] OF ST_Rule_Action; // Действия от Rule Engine
    VI_IO_Modules_Online : ARRAY[1..GVL_CONSTANTS.C_MAX_MODULES] OF BOOL; // Статусы модулей ввода-вывода
END_VAR
VAR_OUTPUT
    VO_Socket_States : ARRAY[1..GVL_CONSTANTS.C_MAX_SOCKETS] OF BOOL; // Выходные состояния розеток
    VO_Internal_States : ARRAY[1..GVL_CONSTANTS.C_MAX_SOCKETS] OF BOOL; // Внутренние состояния для репликации
END_VAR
VAR
    // Socket V2 shadow (phase2)
    fbSocketV2Staging : FB_Socket_V2_Staging_DRAFT;
    L_Socket_V2_Command_Shadow : ST_Socket_Command_V2;
    L_Socket_V2_State_Shadow : ST_Socket_State_V2;
    L_Socket_V2_Shadow_Diff_Found : BOOL;
    L_Socket_V2_Switch_Enabled : BOOL;
    L_Socket_V2_Path_Ready : BOOL;
    L_Socket_Using_Legacy_Fallback : BOOL;
    L_i : INT;
    L_j : INT;
    L_Rule_State : BOOL;
    L_Rule_Active : BOOL;
    L_Internal_State : ARRAY[1..GVL_CONSTANTS.C_MAX_SOCKETS] OF BOOL;
    L_Manual_Trig : ARRAY[1..GVL_CONSTANTS.C_MAX_SOCKETS] OF R_TRIG;
END_VAR

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

L_Socket_V2_Shadow_Diff_Found := FALSE;
L_Socket_V2_Switch_Enabled := TRUE;
L_Socket_V2_Path_Ready := FALSE;
L_Socket_Using_Legacy_Fallback := TRUE;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        // Переход в безопасное состояние при потере связи (отключение всех розеток)
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
            VO_Socket_States[L_j] := FALSE;
        END_FOR;
        RETURN;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    L_Rule_Active := FALSE;
    L_Rule_State := FALSE;

    L_Manual_Trig[L_i](CLK := VI_Manual_Override[L_i]);

    // Ручное переключение
    IF L_Manual_Trig[L_i].Q THEN
        L_Internal_State[L_i] := NOT L_Internal_State[L_i];
    END_IF;

    // Проверка правил для текущей розетки
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_SOCKET THEN
                L_Rule_Active := TRUE;
                L_Rule_State := (VI_Rule_Actions[L_j].Value > 0.5);
                L_Internal_State[L_i] := L_Rule_State; // Синхронизация внутреннего состояния
            ELSIF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_TOGGLE_SOCKET AND VI_Rule_Actions[L_j].Triggered THEN
                L_Internal_State[L_i] := NOT L_Internal_State[L_i]; // Toggle
            END_IF;
        END_IF;
    END_FOR;

    // Аварийное отключение
    IF VI_Fire_Alarm OR VI_Flood_Alarm THEN
        // Розетки 1-4 неотключаемые (холодильник, сервер и т.д.)
        IF L_i > 4 THEN
            VO_Socket_States[L_i] := FALSE;
        ELSE
            // Критические розетки сохраняют свое текущее внутреннее состояние, а не форсируются в TRUE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    ELSIF VI_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY OR VI_Security_Armed THEN
        // Master Off
        IF L_i > 4 THEN
            VO_Socket_States[L_i] := FALSE;
        ELSE
            // Неотключаемые розетки могут управляться вручную
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    ELSE
        // Нормальный режим: состояние определяется внутренним состоянием (ручным или правилом)
        IF L_Rule_Active THEN
            VO_Socket_States[L_i] := L_Rule_State;
        ELSE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    END_IF;
END_FOR;

VO_Internal_States := L_Internal_State;

// ========================================
// Socket V2 shadow execution (phase2)
// ========================================
fbSocketV2Staging(
    VI_Socket_ID := 1,
    VI_Enable := TRUE,
    VI_Target_State := VO_Socket_States[1],
    VI_Manual_Override := VI_Manual_Override[1],
    VI_Safety_Lock := (VI_Fire_Alarm OR VI_Flood_Alarm),
    VI_Scenario_ID := TO_INT(VI_Scenario),

    VI_Is_On := VO_Socket_States[1],
    VI_Manual_Override_Active := VI_Manual_Override[1],
    VI_Safety_Blocked := (VI_Fire_Alarm OR VI_Flood_Alarm),
    VI_Alarm_Active := (VI_Fire_Alarm OR VI_Flood_Alarm),

    VO_Command_Shadow => L_Socket_V2_Command_Shadow,
    VO_State_Shadow => L_Socket_V2_State_Shadow
);

// ========================================
// Socket V2 shadow validation
// ========================================
IF VO_Socket_States[1] <> L_Socket_V2_Command_Shadow.Target_State THEN
    L_Socket_V2_Shadow_Diff_Found := TRUE;
END_IF;
IF VO_Socket_States[1] <> L_Socket_V2_State_Shadow.Is_On THEN
    L_Socket_V2_Shadow_Diff_Found := TRUE;
END_IF;
IF (VI_Fire_Alarm OR VI_Flood_Alarm) <> L_Socket_V2_State_Shadow.Safety_Blocked THEN
    L_Socket_V2_Shadow_Diff_Found := TRUE;
END_IF;

// Guarded Socket V2 enable
IF L_Socket_V2_Switch_Enabled THEN
    IF NOT L_Socket_V2_Shadow_Diff_Found THEN
        L_Socket_V2_Path_Ready := TRUE;
        L_Socket_Using_Legacy_Fallback := FALSE;
    ELSE
        L_Socket_V2_Path_Ready := FALSE;
        L_Socket_Using_Legacy_Fallback := TRUE;
    END_IF;
ELSE
    L_Socket_V2_Path_Ready := FALSE;
    L_Socket_Using_Legacy_Fallback := TRUE;
END_IF;

END_FUNCTION_BLOCK
// >>> BULK_SYNC_ANCHOR: FB_Socket_Manager <<<

FUNCTION_BLOCK FB_System_Health
VAR_INPUT
    VI_Smoke_Detected      : BOOL;
    VI_Gas_Detected        : BOOL;
    VI_CO_Warning_Level    : BOOL;
    VI_CO_Alarm_Level      : BOOL;
    VI_Leak_Detected       : BOOL;

    VI_Sensor_Fault        : BOOL := FALSE;
    VI_IO_Offline          : BOOL := FALSE;
    VI_Comm_Fault          : BOOL := FALSE;
    VI_Watchdog_Fault      : BOOL := FALSE;
    VI_Subsystem_Fault     : BOOL := FALSE;
END_VAR

VAR_OUTPUT
    VO_System_Severity     : E_System_Severity;
    VO_Root_Cause          : E_System_Root_Cause;

    // compatibility outputs for existing orchestration
    VO_Sensor_Fault        : BOOL;
    VO_IO_Fault            : BOOL;
    VO_Comm_Fault          : BOOL;
    VO_Subsystem_Degraded  : BOOL;

    VO_First_Fault_Active  : BOOL;
    VO_First_Fault_Type    : INT;
    VO_First_Fault_Source  : INT;
END_VAR

VO_Sensor_Fault := VI_Sensor_Fault;
VO_IO_Fault := VI_IO_Offline;
VO_Comm_Fault := VI_Comm_Fault;
VO_Subsystem_Degraded := VI_Subsystem_Fault;

VO_System_Severity := E_System_Severity.SEV_NORMAL;
VO_Root_Cause := E_System_Root_Cause.ROOT_NONE;
VO_First_Fault_Active := FALSE;
VO_First_Fault_Type := 0;
VO_First_Fault_Source := 0;

// Priority: FIRE > GAS > CO > WATER > diagnostics
IF VI_Smoke_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_FIRE;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 5;

ELSIF VI_Gas_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_GAS_LEAK;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 6;

ELSIF VI_CO_Alarm_Level THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_CO_CRITICAL;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 7;

ELSIF VI_CO_Warning_Level THEN
    VO_System_Severity := E_System_Severity.SEV_WARNING;
    VO_Root_Cause := E_System_Root_Cause.ROOT_CO_WARNING;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 7;

ELSIF VI_Leak_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_WARNING;
    VO_Root_Cause := E_System_Root_Cause.ROOT_WATER_LEAK;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 8;

ELSIF VI_Watchdog_Fault THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_WATCHDOG_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 9;

ELSIF VI_IO_Offline THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_IO_OFFLINE;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 1;

ELSIF VI_Comm_Fault THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_COMM_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 3;

ELSIF VI_Sensor_Fault THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_SENSOR_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 2;

ELSIF VI_Subsystem_Fault THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 4;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_System_Health <<<

// ==============================================================================
// Блок таймера, привязанный к системному времени (System Timer)
// Назначение:
// - Замена стандартного TON для обеспечения точной выдержки времени,
//   независимой от времени цикла ПЛК, с использованием единого системного времени.
// ==============================================================================
FUNCTION_BLOCK FB_System_Timer
VAR_INPUT
    IN : BOOL; // Вход запуска таймера
    PT : TIME; // Заданное время
    VI_System_Time_MS : UDINT; // Системное время (мс)
END_VAR
VAR_OUTPUT
    Q : BOOL; // Выход: таймер сработал
    ET : TIME; // Прошедшее время
END_VAR
VAR
    L_Start_Time : UDINT;
    L_Running : BOOL;
END_VAR

IF IN THEN
    IF NOT L_Running THEN
        L_Start_Time := VI_System_Time_MS;
        L_Running := TRUE;
        ET := T#0s;
        Q := FALSE;
    ELSE
        // Обработка переполнения UDINT (примерно 49 дней)
        ET := TO_TIME(F_TimeDiff(VI_System_Time_MS, L_Start_Time));

        IF ET >= PT THEN
            Q := TRUE;
            ET := PT;
        ELSE
            Q := FALSE;
        END_IF;
    END_IF;
ELSE
    L_Running := FALSE;
    ET := T#0s;
    Q := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_System_Timer <<<

FUNCTION_BLOCK FB_Watchdog
VAR_INPUT
    VI_System_Time_MS : UDINT;
    VI_Timeout_MS     : UDINT := 2000;
END_VAR

VAR_OUTPUT
    VO_Alive          : BOOL;
    VO_Watchdog_Fault : BOOL;
    VO_Cycle_DT_MS    : UDINT;
END_VAR

VAR
    L_Initialized    : BOOL := FALSE;
    L_Last_Call_MS   : UDINT := 0;
    L_DT_MS          : UDINT := 0;
END_VAR

IF NOT L_Initialized THEN
    L_Initialized := TRUE;
    L_Last_Call_MS := VI_System_Time_MS;
    VO_Cycle_DT_MS := 0;
    VO_Watchdog_Fault := FALSE;
    VO_Alive := TRUE;
    RETURN;
END_IF;

// Measure real time gap between successive calls
L_DT_MS := F_TimeDiff(VI_System_Time_MS, L_Last_Call_MS);
VO_Cycle_DT_MS := L_DT_MS;

// Fault if the task/cycle resumed after an abnormal pause
VO_Watchdog_Fault := (L_DT_MS > VI_Timeout_MS);
VO_Alive := NOT VO_Watchdog_Fault;

// Store current timestamp for next cycle
L_Last_Call_MS := VI_System_Time_MS;
// >>> BULK_SYNC_ANCHOR: FB_Watchdog <<<
